      ],
      "parameters": {
        "jsCode": "// Report File: отчёт в Markdown как файл — для Telegram и для ответа по callback.\nconst r = $input.first().json;\nconst name = `${r.job_id}-${r.title.toLowerCase().replace(/[^\\p{L}\\p{N}]+/gu, '-').replace(/^-|-$/g, '').slice(0, 50) || 'report'}.md`;\nreturn [{\n  json: { ...r, file_name: name },\n  binary: { data: { data: Buffer.from(r.report_md, 'utf8').toString('base64'), mimeType: 'text/markdown', fileName: name, fileExtension: 'md' } },\n}];\n"
      }
    },
    {
      "id": "273e50f4-6f78-5905-a47a-1f5a410c39e8",
