      "parameters": {
        "jsCode": "// Normalize — one shape for an email, a Telegram update and a web form, and a decision about what it is.\nconst cfg = $('Config').first().json;\n// ---- shared helpers ----\nconst MIN = 60000;\nconst nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());\nconst digitsOf = (value) => String(value || '').replace(/[^\\d]/g, '');\n// Phones are stored in one international form, so the same person is recognised however they typed it.\nfunction phoneOf(value) {\n  const rules = cfg.phone || {};\n  let d = digitsOf(value);\n  if (d.startsWith('00')) d = d.slice(2);\n  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {\n    d = rules.country_code + d.slice(rules.national_prefix.length);\n  }\n  return d.length >= 9 && d.length <= 15 ? '+' + d : '';\n}\nfunction emailOf(value) {\n  const e = String(value || '').trim().toLowerCase();\n  return /^[^\\s@<>()\",;]+@[^\\s@<>()\",;]+\\.[a-z]{2,}$/.test(e) ? e : '';\n}\nconst localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {\n  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',\n}).format(new Date(ms));\nfunction localParts(ms) {\n  const parts = {};\n  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;\n  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };\n}\nconst sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;\nconst quoteSheet = (name) => \"'\" + String(name).replace(/'/g, \"''\") + \"'\";\n// Tickets sheet columns. The sheet may start empty: the header is written with the first ticket.\nconst TCOLS = ['id', 'created_at', 'updated_at', 'channel', 'customer', 'name', 'email', 'telegram_chat', 'subject', 'category', 'urgency', 'sentiment',\n  'status', 'summary', 'last_message', 'draft', 'history', 'first_response_at', 'reminded_level', 'assignee', 'kb_answer'];\nconst colLetter = (index) => { let s = ''; let n = index + 1; while (n) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };\nconst TLAST = colLetter(TCOLS.length - 1);\nconst ticketRange = () => `${quoteSheet(cfg.tickets_sheet)}!A1:${TLAST}`;\nconst rowRange = (row) => `${quoteSheet(cfg.tickets_sheet)}!A${row}:${TLAST}${row}`;\nconst batchGetUrl = () => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values:batchGet?ranges=${encodeURIComponent(ticketRange())}&ranges=${encodeURIComponent(`${quoteSheet(cfg.faq_sheet)}!A1:B`)}`;\nfunction tableOf(values) {\n  const rows = values || [];\n  const header = rows.length && rows[0][0] === 'id';\n  return { header, rows: header ? rows.slice(1) : [] };\n}\nconst cell = (row, c) => row[TCOLS.indexOf(c)] || '';\nconst rowObject = (row) => Object.fromEntries(TCOLS.map((c) => [c, cell(row, c)]));\nlet source = null;\nlet item = null;\nfor (const name of ['Support Webhook', 'Telegram Trigger', 'Email Trigger']) {\n  try { item = $(name).first().json; source = name; break; } catch (e) { /* that trigger did not fire */ }\n}\nconst out = (json) => [{ json: Object.assign({ channel: '', kind: 'ignore', customer: {}, subject: '', text: '', batch_url: batchGetUrl(), tickets_url: sheetUrl(encodeURIComponent(ticketRange())) }, json) }];\nconst clip = (text, n) => String(text || '').replace(/\\r/g, '').trim().slice(0, n);\nconst team = String(cfg.team_chat_id);\n\n// Only the part the person wrote: drop quoted history and signatures that mail clients add.\nfunction freshPart(text) {\n  const lines = String(text || '').replace(/\\r/g, '').split('\\n');\n  const stop = lines.findIndex((l) => /^>/.test(l) || /^(On|В|Вт|Пн|Ср|Чт|Пт|Сб|Вс|Am|Le) .{0,80}(wrote|пишет|написал|schrieb|a écrit):?\\s*$/i.test(l.trim()) || /^-{2,}\\s*(Original Message|Исходное сообщение|Пересылаемое)/i.test(l.trim()) || /^-- ?$/.test(l));\n  return (stop >= 0 ? lines.slice(0, stop) : lines).join('\\n').trim();\n}\n\nif (source === 'Support Webhook') {\n  const body = item.body || {};\n  const headers = item.headers || {};\n  const token = headers['x-support-token'] || (item.query || {}).token || body.token;\n  if (!cfg.web_token || cfg.web_token.startsWith('REPLACE') || token !== cfg.web_token) return out({ channel: 'web', kind: 'reject_auth' });\n  const email = emailOf(body.email);\n  const text = clip(body.message || body.text || body.question, 4000);\n  if (!text) return out({ channel: 'web', kind: 'reject_empty' });\n  const sessionId = clip(body.session || body.session_id || '', 80);\n  return out({ channel: 'web', kind: 'message', subject: clip(body.subject, 200),\n    customer: { id: email || (sessionId ? 'web:' + sessionId : 'web:' + digitsOf(Date.now())), name: clip(body.name, 120), email }, text });\n}\n\nif (source === 'Telegram Trigger') {\n  const cb = item.callback_query;\n  if (cb) {\n    if (String(cb.message && cb.message.chat && cb.message.chat.id) !== team) return out({ channel: 'telegram', kind: 'ignore' });\n    const [action, ticket] = String(cb.data || '').split(':');\n    if (!['send', 'skip'].includes(action) || !ticket) return out({ channel: 'telegram', kind: 'ignore' });\n    return out({ channel: 'telegram', kind: action === 'send' ? 'approve' : 'dismiss', callback: { id: cb.id, ticket, chat: cb.message.chat.id, message_id: cb.message.message_id, by: [cb.from.first_name, cb.from.last_name].filter(Boolean).join(' ') || cb.from.username || '' } });\n  }\n  const m = item.message;\n  if (!m || !m.chat) return out({ channel: 'telegram', kind: 'ignore' });\n  if (String(m.chat.id) === team) {\n    // A teammate answers a customer by replying to the bot's message about the ticket.\n    const quoted = m.reply_to_message && m.reply_to_message.text ? m.reply_to_message.text : '';\n    const ref = /ID: (T[0-9A-Z-]+)/.exec(quoted);\n    if (ref && m.text) return out({ channel: 'telegram', kind: 'team_reply', text: clip(m.text, 4000), callback: { ticket: ref[1], by: [m.from.first_name, m.from.last_name].filter(Boolean).join(' ') } });\n    return out({ channel: 'telegram', kind: 'ignore' });\n  }\n  if (m.chat.type && m.chat.type !== 'private') return out({ channel: 'telegram', kind: 'ignore' });\n  const name = [m.from && m.from.first_name, m.from && m.from.last_name].filter(Boolean).join(' ') || (m.from && m.from.username) || '';\n  const customer = { id: 'tg:' + m.from.id, name, telegram_chat: String(m.chat.id) };\n  if (/^\\/start\\b/.test(m.text || '')) return out({ channel: 'telegram', kind: 'greet', customer });\n  const media = m.photo ? '[фото]' : m.voice ? '[голосовое сообщение]' : m.document ? '[файл]' : m.video ? '[видео]' : m.sticker ? '[стикер]' : '';\n  const text = clip(m.text || m.caption || '', 4000);\n  if (!text && !media) return out({ channel: 'telegram', kind: 'ignore' });\n  return out({ channel: 'telegram', kind: 'message', customer, text: [media, text].filter(Boolean).join(' '), has_media: Boolean(media) });\n}\n\n// Email\nconst fromRaw = item.from && typeof item.from === 'object' ? ((item.from.value || [])[0] || {}) : item.from;\nconst fromText = typeof fromRaw === 'string' ? fromRaw : `${fromRaw.name || ''} <${fromRaw.address || ''}>`;\nconst address = emailOf((/<([^>]+)>/.exec(fromText) || [null, fromText])[1]);\nconst sender = fromText.replace(/<[^>]*>/, '').replace(/\"/g, '').trim();\nconst ours = emailOf((/<([^>]+)>/.exec((cfg.email || {}).from || '') || [null, (cfg.email || {}).from || ''])[1]);\nconst subject = clip(item.subject, 200);\n// Never answer robots: bounces, auto-replies and our own messages would start a loop.\nconst robot = !address || address === ours || /^(no-?reply|mailer-daemon|postmaster|bounce|notifications?)@/i.test(address)\n  || /^(auto|automatic reply|автоответ|out of office|недоставлено|undeliverable|delivery status)/i.test(subject)\n  || String((item.headers && (item.headers['auto-submitted'] || item.headers['Auto-Submitted'])) || 'no') !== 'no';\nif (robot) return out({ channel: 'email', kind: 'ignore', subject });\nconst plain = item.textPlain || item.text || String(item.textHtml || item.html || '').replace(/<[^>]+>/g, ' ');\nconst text = clip(freshPart(plain), 4000);\nif (!text) return out({ channel: 'email', kind: 'ignore', subject });\nreturn out({ channel: 'email', kind: 'message', subject, customer: { id: address, name: clip(sender, 120), email: address }, text });\n"
      },
