      "id": "04fc6ba4-9ebc-55c3-9bd3-f01def743e69",
      "name": "Read Tickets",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4.2,
      "position": [
        20,
        400
      ],
      "credentials": {
        "googleSheetsOAuth2Api": {
          "id": "REPLACE_ME",
