import React from "react";
import { interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { useLook } from "./look";

/**
 * Word-timed captions. The timeline comes from the captions-explainer skill's
 * srt_to_timeline.py: pages of a few words, each word with its own start and
 * end in seconds. One page is on screen at a time; the spoken word carries the
 * accent.
 */

export type CaptionWord = { text: string; start: number; end: number };
export type CaptionPage = { start: number; end: number; words: CaptionWord[] };
export type CaptionTimeline = { pages: CaptionPage[] };

export type CaptionMode =
  /** Words pop in as they are spoken; the spoken word sits on an accent block. */
  | "pop"
  /** The whole page is visible; the spoken word lights up. Calmer, easier to read. */
  | "karaoke";

export function CaptionTrack({
  timeline,
  mode = "pop",
  size = 84,
  maxWidth = 900,
  uppercase = false,
}: {
  timeline: CaptionTimeline;
  mode?: CaptionMode;
  size?: number;
  maxWidth?: number;
  uppercase?: boolean;
}) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const { style, fonts } = useLook();
  const t = frame / fps;
  const page = timeline.pages.find((p) => t >= p.start && t < p.end);
  if (!page) return null;
  const pageAge = frame - Math.round(page.start * fps);
  const pageIn = spring({ frame: pageAge, fps, config: { damping: 200, stiffness: 220 } });

  return (
    <div
      style={{
        display: "flex",
        flexWrap: "wrap",
        justifyContent: "center",
        columnGap: size * 0.26,
        rowGap: size * 0.08,
        maxWidth,
        fontFamily: fonts.display,
        fontWeight: style.fonts.display.weight,
        fontSize: size,
        lineHeight: 1.05,
        letterSpacing: `${Math.max(style.fonts.display.tracking, -0.03)}em`,
        textTransform: uppercase ? "uppercase" : "none",
        textAlign: "center",
        transform: `translateY(${(1 - pageIn) * 30}px)`,
      }}
    >
      {page.words.map((word, i) => {
        const start = Math.round(word.start * fps);
        const age = frame - start;
        const spoken = t >= word.start;
        const active = t >= word.start && t < Math.max(word.end, word.start + 0.12);
        const pop = spring({ frame: age, fps, config: { damping: 14, stiffness: 260, mass: 0.6 } });
        const shown = mode === "karaoke" || spoken;
        const scale = mode === "pop" ? interpolate(pop, [0, 1], [0.6, 1]) : 1;
        return (
          <span
            key={`${word.text}-${i}`}
            style={{
              position: "relative",
              display: "inline-block",
              isolation: "isolate",
              opacity: shown ? (mode === "karaoke" && !spoken ? 0.38 : 1) : 0,
              transform: `scale(${scale})`,
              color: active ? style.colors.onAccent : style.colors.ink,
              padding: "0 0.1em",
              margin: "0 -0.1em",
              textShadow: active ? "none" : "0 4px 24px rgba(0,0,0,0.35)",
            }}
          >
            {active && (
              <span
                style={{
                  position: "absolute",
                  inset: "0.04em -0.02em 0.02em",
                  background: style.colors.accent,
                  borderRadius: Math.min(style.radius, 10),
                  zIndex: -1,
                }}
              />
            )}
            {word.text}
          </span>
        );
      })}
    </div>
  );
}

import React from "react";
import { useCurrentFrame, useVideoConfig } from "remotion";
import { evolvePath } from "@remotion/paths";
import { ramp } from "../lib/motion";
import { useLook, useMonoType } from "./look";

/**
 * Chart primitives. They draw exactly the numbers they are given: scales,
 * ticks and formats are computed beforehand by the data-story skill's
 * csv_to_chart.py, so nothing here rounds or guesses.
 */

export type ChartSpec = {
  kind: "bar" | "line";
  labels: string[];
  series: { name: string; values: number[] }[];
  scale: { min: number; max: number; ticks: number[] };
  format: { decimals: number; prefix: string; suffix: string };
  highlight?: { series: number; index: number } | null;
};

/** Formats a number the way people in the given locale write it: 12 500,5. */
export function formatNumber(value: number, decimals: number, locale = "ru-RU"): string {
  return new Intl.NumberFormat(locale, { minimumFractionDigits: decimals, maximumFractionDigits: decimals }).format(value);
}

/** A number that counts up to its value. Tabular figures, so it does not jitter. */
export function Counter({
  value,
  from = 0,
  delay = 0,
  duration,
  decimals = 0,
  prefix = "",
  suffix = "",
  locale,
  style: css,
}: {
  value: number;
  from?: number;
  delay?: number;
  duration?: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
  locale?: string;
  style?: React.CSSProperties;
}) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const { style } = useLook();
  const p = ramp(frame, delay, duration ?? Math.round(fps * style.beat * 3), style.ease.out);
  const current = from + (value - from) * p;
  return (
    <span style={{ fontVariantNumeric: "tabular-nums", ...css }}>
      {prefix}
      {formatNumber(current, decimals, locale)}
      {suffix}
    </span>
  );
}

const toY = (value: number, spec: ChartSpec, height: number) =>
  height - ((value - spec.scale.min) / (spec.scale.max - spec.scale.min || 1)) * height;

function Axis({ spec, width, height, delay }: { spec: ChartSpec; width: number; height: number; delay: number }) {
  const frame = useCurrentFrame();
  const { style } = useLook();
  const mono = useMonoType();
  return (
    <>
      {spec.scale.ticks.map((tick, i) => {
        const p = ramp(frame, delay + i * 2, 18, style.ease.out);
        const y = toY(tick, spec, height);
        return (
          <div key={tick} style={{ position: "absolute", left: 0, top: y, width: width * p, height: 1, background: style.colors.line }}>
            <span style={{ ...mono, position: "absolute", right: "100%", top: -11, paddingRight: 18, fontSize: 18, opacity: p, letterSpacing: "0.04em" }}>
              {formatNumber(tick, spec.format.decimals)}
            </span>
          </div>
        );
      })}
    </>
  );
}

export type Delta = { from: number; to: number; label: string; at: number };

/**
 * Vertical bars that grow in sequence; the highlighted one takes the accent.
 * `delta` draws a dashed level from one bar to another and brackets the
 * difference with a label, at `at` seconds.
 */
export function Bars({ spec, width, height, delay = 0, step = 4, delta }: { spec: ChartSpec; width: number; height: number; delay?: number; step?: number; delta?: Delta }) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const { style } = useLook();
  const mono = useMonoType();
  const values = spec.series[0]?.values ?? [];
  const slot = width / values.length;
  const barWidth = slot * 0.62;
  const zero = toY(Math.max(spec.scale.min, 0), spec, height);
  return (
    <div style={{ position: "relative", width, height }}>
      <Axis spec={spec} width={width} height={height} delay={delay} />
      {values.map((value, i) => {
        const p = ramp(frame, delay + 10 + i * step, Math.round(fps * style.beat * 1.8), style.ease.out);
        const top = toY(value, spec, height);
        const hot = spec.highlight ? spec.highlight.index === i : i === values.length - 1;
        const h = (zero - top) * p;
        return (
          <div key={i} style={{ position: "absolute", left: i * slot + (slot - barWidth) / 2, width: barWidth, top: zero - h, height: Math.max(h, 0) }}>
            <div style={{ position: "absolute", inset: 0, background: hot ? style.colors.accent : style.colors.ink, opacity: hot ? 1 : 0.18, borderRadius: `${Math.min(style.radius, 6)}px ${Math.min(style.radius, 6)}px 0 0` }} />
            <span style={{ ...mono, position: "absolute", top: -42, left: 0, right: 0, textAlign: "center", fontSize: 22, color: hot ? style.colors.accent : style.colors.ink, opacity: ramp(frame, delay + 24 + i * step, 10), letterSpacing: "0.02em" }}>
              {formatNumber(value * p, spec.format.decimals)}
            </span>
            <span style={{ ...mono, position: "absolute", top: h + 18, left: -20, right: -20, textAlign: "center", fontSize: 18 }}>{spec.labels[i]}</span>
          </div>
        );
      })}
      {delta && <DeltaMark spec={spec} delta={delta} slot={slot} height={height} />}
    </div>
  );
}

function DeltaMark({ spec, delta, slot, height }: { spec: ChartSpec; delta: Delta; slot: number; height: number }) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const { style, fonts } = useLook();
  const values = spec.series[0]?.values ?? [];
  const start = Math.round(delta.at * fps);
  const level = ramp(frame, start, Math.round(fps * style.beat * 1.6), style.ease.inOut);
  const bracket = ramp(frame, start + 12, Math.round(fps * style.beat * 1.2), style.ease.out);
  const label = ramp(frame, start + 22, Math.round(fps * style.beat), style.ease.out);
  const x0 = delta.from * slot + slot / 2;
  const x1 = delta.to * slot + slot / 2 + slot * 0.42;
  const y0 = toY(values[delta.from], spec, height);
  const y1 = toY(values[delta.to], spec, height);
  return (
    <>
      <div style={{ position: "absolute", left: x0, top: y0, width: (x1 - x0) * level, borderTop: `2px dashed ${style.colors.accent}` }} />
      <div style={{ position: "absolute", left: x1, top: y0, width: 2, height: (y1 - y0) * bracket, background: style.colors.accent }} />
      <div style={{ position: "absolute", left: x1 - 10, top: y1, width: 12, height: 2, background: style.colors.accent, opacity: bracket }} />
      <div
        style={{
          position: "absolute",
          left: x1 + 22,
          top: (y0 + y1) / 2 - 34,
          fontFamily: fonts.display,
          fontWeight: style.fonts.display.weight,
          letterSpacing: `${style.fonts.display.tracking}em`,
          fontSize: 56,
          color: style.colors.onAccent,
          background: style.colors.accent,
          padding: "2px 14px 6px",
          borderRadius: Math.min(style.radius, 8),
          opacity: label,
          transform: `translateX(${(1 - label) * -20}px)`,
          whiteSpace: "nowrap",
        }}
      >
        {delta.label}
      </div>
    </>
  );
}

/** A line that draws itself, with a dot riding its tip and a value tag at the end. */
export function Line({ spec, width, height, delay = 0, duration }: { spec: ChartSpec; width: number; height: number; delay?: number; duration?: number }) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const { style } = useLook();
  const mono = useMonoType();
  const length = duration ?? Math.round(fps * style.beat * 5);
  return (
    <div style={{ position: "relative", width, height }}>
      <Axis spec={spec} width={width} height={height} delay={delay} />
      <svg width={width} height={height} style={{ position: "absolute", inset: 0, overflow: "visible" }}>
        {spec.series.map((series, s) => {
          const points = series.values.map((v, i) => [(i / (series.values.length - 1 || 1)) * width, toY(v, spec, height)] as const);
          const d = points.map(([x, y], i) => `${i ? "L" : "M"} ${x.toFixed(1)} ${y.toFixed(1)}`).join(" ");
          const p = ramp(frame, delay + 12 + s * 8, length, style.ease.inOut);
          const evolved = evolvePath(p, d);
          const colour = s === 0 ? style.colors.accent : style.colors.ink;
          // Position of the tip: interpolate along the polyline by index.
          const f = p * (points.length - 1);
          const i0 = Math.min(points.length - 2, Math.floor(f));
          const t = f - i0;
          const tip = points.length > 1 ? [points[i0][0] + (points[i0 + 1][0] - points[i0][0]) * t, points[i0][1] + (points[i0 + 1][1] - points[i0][1]) * t] : points[0];
          const value = series.values[i0] + (series.values[Math.min(i0 + 1, series.values.length - 1)] - series.values[i0]) * t;
          return (
            <g key={series.name}>
              <path d={d} fill="none" stroke={colour} strokeWidth={s === 0 ? 6 : 3} strokeLinejoin="round" strokeLinecap="round" opacity={s === 0 ? 1 : 0.45} strokeDasharray={evolved.strokeDasharray} strokeDashoffset={evolved.strokeDashoffset} />
              {s > 0 && (
                <foreignObject x={points[points.length - 1][0] + 18} y={points[points.length - 1][1] - 16} width={260} height={40}>
                  <div style={{ ...mono, fontSize: 18, opacity: ramp(frame, delay + 12 + s * 8 + length, 10) }}>{series.name}</div>
                </foreignObject>
              )}
              {s === 0 && p > 0 && (
                <>
                  <circle cx={tip[0]} cy={tip[1]} r={12} fill={style.colors.ground} stroke={colour} strokeWidth={5} />
                  <foreignObject x={tip[0] + 22} y={tip[1] - 64} width={300} height={60}>
                    <div style={{ ...mono, fontSize: 26, color: colour, letterSpacing: "0.02em" }}>
                      {spec.format.prefix}
                      {formatNumber(value, spec.format.decimals)}
                      {spec.format.suffix}
                    </div>
                  </foreignObject>
                </>
              )}
            </g>
          );
        })}
      </svg>
      <div style={{ position: "absolute", top: height + 20, left: 0, right: 0, display: "flex", justifyContent: "space-between" }}>
        {spec.labels.map((label, i) => (
          <span key={i} style={{ ...mono, fontSize: 18, opacity: ramp(frame, delay + i, 10) }}>
            {label}
          </span>
        ))}
      </div>
    </div>
  );
}

import React from "react";
import { Img, interpolate, useCurrentFrame, useVideoConfig } from "remotion";
import { mix, ramp } from "../lib/motion";
import { useLook, useMonoType } from "./look";

/**
 * Device frames, a cursor and callouts for product promos. Coordinates on a
 * screenshot are fractions (0–1) of its width and height, so the same shot
 * list works whatever size the screenshots were captured at.
 */

export type Zoom = { x: number; y: number; scale: number; at: number; hold?: number };

/** Scale and offset of the camera on a screenshot at the current frame. */
export function useZoom(zoom: Zoom | undefined, width: number, height: number) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const { style } = useLook();
  let scale = 1;
  let x = 0.5;
  let y = 0.5;
  if (zoom) {
    const start = Math.round(zoom.at * fps);
    const hold = Math.round((zoom.hold ?? 1.4) * fps);
    const move = Math.round(style.beat * fps * 1.8);
    const p = Math.min(ramp(frame, start, move, style.ease.inOut), 1 - ramp(frame, start + move + hold, move, style.ease.inOut));
    scale = mix(1, zoom.scale, p);
    x = mix(0.5, zoom.x, p);
    y = mix(0.5, zoom.y, p);
  }
  // Keep the zoomed point centred without showing past the image edges.
  const tx = Math.max(Math.min((0.5 - x) * width * scale, ((scale - 1) * width) / 2), (-(scale - 1) * width) / 2);
  const ty = Math.max(Math.min((0.5 - y) * height * scale, ((scale - 1) * height) / 2), (-(scale - 1) * height) / 2);
  /** Where a point on the screenshot (fractions) is in the window right now (fractions). */
  const map = (px: number, py: number) => ({
    x: 0.5 + (px - 0.5) * scale + tx / width,
    y: 0.5 + (py - 0.5) * scale + ty / height,
  });
  return { scale, tx, ty, map };
}

/**
 * A screenshot that can push in on a point. The zoom eases in, holds, eases
 * out; `x`/`y` is the point that ends up in the middle of the window.
 */
export function Screen({ src, zoom, width, height }: { src: string; zoom?: Zoom; width: number; height: number }) {
  const { scale, tx, ty } = useZoom(zoom, width, height);
  return (
    <div style={{ position: "absolute", inset: 0, overflow: "hidden" }}>
      <Img
        src={src}
        style={{ width, height, objectFit: "cover", objectPosition: "top center", transform: `translate(${tx}px, ${ty}px) scale(${scale})`, transformOrigin: "center center" }}
      />
    </div>
  );
}

/** A desktop browser window: a slim bar with the address, then the page. */
export function BrowserFrame({ url, width, height, children }: { url?: string; width: number; height: number; children: React.ReactNode }) {
  const { style } = useLook();
  const mono = useMonoType();
  const bar = Math.round(height * 0.055);
  return (
    <div
      style={{
        width,
        height: height + bar,
        borderRadius: Math.min(style.radius + 6, 22),
        overflow: "hidden",
        background: style.colors.panel,
        border: `1px solid ${style.colors.line}`,
        boxShadow: "0 60px 120px -40px rgba(0,0,0,0.65), 0 20px 40px -20px rgba(0,0,0,0.5)",
      }}
    >
      <div style={{ height: bar, display: "flex", alignItems: "center", gap: 10, padding: "0 22px", borderBottom: `1px solid ${style.colors.line}` }}>
        {[0, 1, 2].map((i) => (
          <span key={i} style={{ width: 12, height: 12, borderRadius: 6, background: style.colors.line }} />
        ))}
        {url && (
          <span style={{ ...mono, marginLeft: 22, fontSize: bar * 0.34, letterSpacing: "0.04em", textTransform: "none", color: style.colors.muted }}>
            {url}
          </span>
        )}
      </div>
      <div style={{ position: "relative", width, height }}>{children}</div>
    </div>
  );
}

/** A phone: rounded body, a narrow bezel, the screen inside. */
export function PhoneFrame({ width, children }: { width: number; children: React.ReactNode }) {
  const { style } = useLook();
  const height = width * 2.08;
  const bezel = width * 0.035;
  return (
    <div style={{ width, height, borderRadius: width * 0.14, background: "#0a0a0a", padding: bezel, boxShadow: `0 0 0 2px ${style.colors.line}, 0 60px 120px -40px rgba(0,0,0,0.7)` }}>
      <div style={{ position: "relative", width: "100%", height: "100%", borderRadius: width * 0.11, overflow: "hidden", background: style.colors.panel }}>{children}</div>
    </div>
  );
}

export type CursorStop = { x: number; y: number; at: number };

/**
 * A pointer that travels between stops with the style's easing, and shows a
 * ring when it clicks. Stops are in seconds and fractions of the frame it sits in.
 */
export function Cursor({
  stops,
  clicks = [],
  width,
  height,
  map = (x, y) => ({ x, y }),
}: {
  stops: CursorStop[];
  clicks?: number[];
  width: number;
  height: number;
  /** Screenshot → window mapping from useZoom, so the pointer rides the camera. */
  map?: (x: number, y: number) => { x: number; y: number };
}) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const { style } = useLook();
  if (!stops.length) return null;
  const frames = stops.map((s) => Math.round(s.at * fps));
  let x = stops[0].x;
  let y = stops[0].y;
  for (let i = 1; i < stops.length; i++) {
    const p = ramp(frame, frames[i - 1], frames[i] - frames[i - 1], style.ease.inOut);
    if (frame >= frames[i - 1]) {
      x = mix(stops[i - 1].x, stops[i].x, p);
      y = mix(stops[i - 1].y, stops[i].y, p);
    }
  }
  ({ x, y } = map(x, y));
  const visible = ramp(frame, frames[0] - 6, 6);
  let press = 0;
  let ring = 0;
  for (const click of clicks) {
    const c = Math.round(click * fps);
    const age = frame - c;
    if (age >= -3 && age < 4) press = 1;
    if (age >= 0 && age < 18) ring = age / 18;
  }
  return (
    <div style={{ position: "absolute", left: x * width, top: y * height, opacity: visible, pointerEvents: "none" }}>
      {ring > 0 && (
        <div
          style={{
            position: "absolute",
            left: -40 * (0.4 + ring),
            top: -40 * (0.4 + ring),
            width: 80 * (0.4 + ring),
            height: 80 * (0.4 + ring),
            borderRadius: "50%",
            border: `4px solid ${style.colors.accent}`,
            opacity: 1 - ring,
          }}
        />
      )}
      <svg width={44} height={44} viewBox="0 0 24 24" style={{ transform: `scale(${press ? 0.86 : 1})`, transformOrigin: "4px 3px", filter: "drop-shadow(0 6px 10px rgba(0,0,0,0.45))" }}>
        <path d="M4 3 L4 19 L8.6 14.6 L11.6 21 L14.4 19.8 L11.4 13.5 L18 13.5 Z" fill="#ffffff" stroke="#0a0a0a" strokeWidth={1.4} strokeLinejoin="round" />
      </svg>
    </div>
  );
}

/**
 * A label with a leader line pointing at a spot. The line draws first, then
 * the label rises — the eye follows the line to the thing.
 */
export function Callout({
  x,
  y,
  text,
  at,
  side = "right",
  length = 160,
  width,
  height,
}: {
  x: number;
  y: number;
  text: string;
  at: number;
  side?: "left" | "right";
  length?: number;
  width: number;
  height: number;
}) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const { style, fonts } = useLook();
  const start = Math.round(at * fps);
  const line = ramp(frame, start, Math.round(fps * style.beat), style.ease.out);
  const label = ramp(frame, start + 8, Math.round(fps * style.beat), style.ease.out);
  const dir = side === "right" ? 1 : -1;
  return (
    <div style={{ position: "absolute", left: x * width, top: y * height, pointerEvents: "none" }}>
      <div style={{ position: "absolute", left: -9, top: -9, width: 18, height: 18, borderRadius: 9, background: style.colors.accent, transform: `scale(${interpolate(line, [0, 0.3, 1], [0, 1.3, 1])})` }} />
      <div style={{ position: "absolute", top: 0, left: dir > 0 ? 0 : -length * line, width: length * line, height: 2, background: style.colors.accent }} />
      <div
        style={{
          position: "absolute",
          top: -30,
          left: dir > 0 ? length + 16 : undefined,
          right: dir < 0 ? length + 16 : undefined,
          whiteSpace: "nowrap",
          fontFamily: fonts.text,
          fontWeight: 700,
          fontSize: 40,
          color: style.colors.onAccent,
          background: style.colors.accent,
          padding: "6px 18px 8px",
          borderRadius: Math.min(style.radius, 10),
          opacity: label,
          transform: `translateY(${(1 - label) * 24}px)`,
        }}
      >
        {text}
      </div>
    </div>
  );
}

import React, { createContext, useContext, useEffect, useMemo, useState } from "react";
import { useDelayRender } from "remotion";
import { loadStyleFonts, type StyleFonts } from "../styles/fonts";
import { getStyle, type Style } from "../styles/styles";

/**
 * The style and its loaded fonts, available to every component below a
 * composition. Components read colours and type from here instead of taking
 * them as props, so switching `style` in a composition's props restyles all
 * of it at once.
 */
type Look = { style: Style; fonts: StyleFonts };

const LookContext = createContext<Look | null>(null);

export function LookProvider({ styleId, children }: { styleId?: string; children: React.ReactNode }) {
  const style = getStyle(styleId);
  const { fonts, ready } = useMemo(() => loadStyleFonts(style), [style]);
  const { delayRender, continueRender, cancelRender } = useDelayRender();
  const [handle] = useState(() => delayRender(`Loading fonts for style "${style.id}"`));
  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    ready.then(() => {
      setLoaded(true);
      continueRender(handle);
    }, cancelRender);
  }, [ready, handle, continueRender, cancelRender]);
  // Nothing is drawn until the faces are in: text fitted to a fallback font
  // would be the wrong size in the final frame.
  if (!loaded) return null;
  return <LookContext.Provider value={{ style, fonts }}>{children}</LookContext.Provider>;
}

export function useLook(): Look {
  const look = useContext(LookContext);
  if (!look) throw new Error("Wrap the composition in <LookProvider>.");
  return look;
}

/** CSS for the display face of the current style. */
export function useDisplayType(): React.CSSProperties {
  const { style, fonts } = useLook();
  const role = style.fonts.display;
  return {
    fontFamily: fonts.display,
    fontWeight: role.weight,
    letterSpacing: `${role.tracking}em`,
    lineHeight: role.leading,
    fontStyle: role.italic ? "italic" : "normal",
    textTransform: role.uppercase ? "uppercase" : "none",
    color: style.colors.ink,
    // Print styles: a second ink slightly off register, like a two-colour press.
    textShadow: style.texture.misregister ? `${style.texture.misregister}px ${style.texture.misregister * 0.6}px 0 ${style.colors.accent}` : undefined,
  };
}

export function useMonoType(): React.CSSProperties {
  const { style, fonts } = useLook();
  return {
    fontFamily: fonts.mono,
    fontWeight: style.fonts.mono.weight,
    letterSpacing: "0.14em",
    textTransform: "uppercase",
    color: style.colors.muted,
    fontVariantNumeric: "tabular-nums",
  };
}

export function useTextType(): React.CSSProperties {
  const { style, fonts } = useLook();
  const role = style.fonts.text;
  return {
    fontFamily: fonts.text,
    fontWeight: role.weight,
    letterSpacing: `${role.tracking}em`,
    lineHeight: role.leading,
    color: style.colors.ink,
  };
}

import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from "remotion";
import { ramp } from "../lib/motion";
import { useLook, useMonoType } from "./look";

/**
 * Film grain from an SVG noise filter whose seed changes every frame. Cheap,
 * deterministic, and enough to stop flat colour from looking like a slide.
 */
export function Grain({ amount }: { amount?: number }) {
  const frame = useCurrentFrame();
  const { style } = useLook();
  const opacity = amount ?? style.texture.grain;
  if (opacity <= 0) return null;
  const id = "grain-filter";
  return (
    <AbsoluteFill style={{ pointerEvents: "none", opacity, mixBlendMode: "normal" }}>
      <svg width="100%" height="100%">
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="2" seed={frame % 97} stitchTiles="stitch" />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
}

function Scanlines() {
  const { style } = useLook();
  return (
    <AbsoluteFill
      style={{
        pointerEvents: "none",
        background: `repeating-linear-gradient(0deg, transparent 0px, transparent 3px, ${style.colors.ground}55 3px, ${style.colors.ground}55 4px)`,
      }}
    />
  );
}

/** The ground of every composition: colour, texture, and the content between. */
export function Stage({ children, grain }: { children: React.ReactNode; grain?: number }) {
  const { style } = useLook();
  return (
    <AbsoluteFill style={{ backgroundColor: style.colors.ground, overflow: "hidden" }}>
      {children}
      {style.texture.scanlines && <Scanlines />}
      <Grain amount={grain} />
    </AbsoluteFill>
  );
}

/** Timecode as HH:MM:SS:FF — reads as "made by someone who edits video". */
export function timecode(frame: number, fps: number): string {
  const ff = frame % fps;
  const total = Math.floor(frame / fps);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${pad(Math.floor(total / 3600))}:${pad(Math.floor(total / 60) % 60)}:${pad(total % 60)}:${pad(ff)}`;
}

/**
 * Small mono labels in the four corners, like the margins of a printed
 * poster. Pass `null` to leave a corner empty; "{tc}" becomes the timecode.
 */
export function Corners({
  tl,
  tr = "{tc}",
  bl,
  br,
  inset = 56,
  size = 20,
  delay = 0,
}: {
  tl?: string | null;
  tr?: string | null;
  bl?: string | null;
  br?: string | null;
  inset?: number;
  size?: number;
  delay?: number;
}) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const mono = useMonoType();
  const opacity = ramp(frame, delay, 12);
  const fill = (value?: string | null) => (value ?? "").replace("{tc}", timecode(frame, fps));
  const base: React.CSSProperties = { ...mono, position: "absolute", fontSize: size, opacity, whiteSpace: "nowrap" };
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      {tl && <div style={{ ...base, left: inset, top: inset }}>{fill(tl)}</div>}
      {tr && <div style={{ ...base, right: inset, top: inset }}>{fill(tr)}</div>}
      {bl && <div style={{ ...base, left: inset, bottom: inset }}>{fill(bl)}</div>}
      {br && <div style={{ ...base, right: inset, bottom: inset }}>{fill(br)}</div>}
    </AbsoluteFill>
  );
}

/**
 * Hairline grid that draws itself in. Columns are the layout grid the
 * composition actually uses — show it only when the style calls for it.
 */
export function GridLines({
  columns = 6,
  rows = 0,
  inset = 56,
  delay = 0,
  duration = 24,
}: {
  columns?: number;
  rows?: number;
  inset?: number;
  delay?: number;
  duration?: number;
}) {
  const frame = useCurrentFrame();
  const { style } = useLook();
  const { width, height } = useVideoConfig();
  const lines: React.ReactNode[] = [];
  for (let i = 0; i <= columns; i++) {
    const p = ramp(frame, delay + i * 2, duration, style.ease.out);
    const x = inset + ((width - inset * 2) * i) / columns;
    lines.push(
      <div key={`c${i}`} style={{ position: "absolute", left: x, top: inset, width: 1, height: (height - inset * 2) * p, background: style.colors.line }} />,
    );
  }
  for (let j = 0; j <= rows; j++) {
    if (!rows) break;
    const p = ramp(frame, delay + j * 2, duration, style.ease.out);
    const y = inset + ((height - inset * 2) * j) / rows;
    lines.push(
      <div key={`r${j}`} style={{ position: "absolute", top: y, left: inset, height: 1, width: (width - inset * 2) * p, background: style.colors.line }} />,
    );
  }
  return <AbsoluteFill style={{ pointerEvents: "none" }}>{lines}</AbsoluteFill>;
}

import React from "react";
import { interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { fitText } from "@remotion/layout-utils";
import { ramp, styledFrame } from "../lib/motion";
import { useLook } from "./look";

/**
 * Text moves. Each one animates a single, honest property — position inside a
 * mask, scale, letter spacing, a marker behind the words — because type that
 * fades, slides, spins and blurs at once reads as a template.
 */

/** Splits text into words, keeping punctuation attached to its word. */
export const splitWords = (text: string) => text.split(/\s+/).filter(Boolean);

/**
 * A line that rises out of an invisible slot. The slot is padded so
 * descenders and Cyrillic diacritics are not clipped.
 */
export function MaskLine({
  children,
  delay = 0,
  duration,
  from = "below",
  exitAt,
  style: css,
}: {
  children: React.ReactNode;
  delay?: number;
  duration?: number;
  from?: "below" | "above";
  /** Frame at which the line drops out again, if it should leave before the cut. */
  exitAt?: number;
  style?: React.CSSProperties;
}) {
  const raw = useCurrentFrame();
  const { fps } = useVideoConfig();
  const { style } = useLook();
  const frame = styledFrame(raw, style);
  const length = duration ?? Math.round(style.beat * fps * 1.4);
  const enter = ramp(frame, delay, length, style.ease.out);
  const exit = exitAt === undefined ? 0 : ramp(frame, exitAt, Math.round(length * 0.7), style.ease.in);
  const sign = from === "below" ? 1 : -1;
  const y = (1 - enter) * 115 * sign - exit * 135 * sign;
  return (
    <span style={{ display: "inline-block", overflow: "hidden", padding: "0.12em 0.04em 0.16em", margin: "-0.12em -0.04em -0.16em", verticalAlign: "top", ...css }}>
      <span style={{ display: "inline-block", transform: `translateY(${y}%)`, willChange: "transform" }}>{children}</span>
    </span>
  );
}

/** Words that rise one after another. `highlight` puts a marker behind words by index. */
export function Words({
  text,
  delay = 0,
  step = 3,
  highlight = [],
  exitAt,
  gap = "0.24em",
}: {
  text: string;
  delay?: number;
  step?: number;
  highlight?: number[];
  exitAt?: number;
  gap?: string;
}) {
  const words = splitWords(text);
  return (
    <span style={{ display: "inline-flex", flexWrap: "wrap", columnGap: gap }}>
      {words.map((word, i) => (
        <MaskLine key={`${word}-${i}`} delay={delay + i * step} exitAt={exitAt === undefined ? undefined : exitAt + i * 1}>
          {highlight.includes(i) ? <Marker delay={delay + i * step + 6}>{word}</Marker> : word}
        </MaskLine>
      ))}
    </span>
  );
}

/** A block of accent colour that wipes in behind text; the text flips to the on-accent colour. */
export function Marker({ children, delay = 0, duration }: { children: React.ReactNode; delay?: number; duration?: number }) {
  const frame = styledFrame(useCurrentFrame(), useLook().style);
  const { fps } = useVideoConfig();
  const { style } = useLook();
  const p = ramp(frame, delay, duration ?? Math.round(style.beat * fps), style.ease.inOut);
  return (
    <span style={{ position: "relative", display: "inline-block", padding: "0 0.12em", margin: "0 -0.12em" }}>
      <span
        style={{
          position: "absolute",
          inset: "0.02em 0 0.04em",
          background: style.colors.accent,
          transform: `scaleX(${p})`,
          transformOrigin: "left center",
          borderRadius: Math.min(style.radius, 8),
        }}
      />
      <span style={{ position: "relative", color: p > 0.5 ? style.colors.onAccent : "inherit" }}>{children}</span>
    </span>
  );
}

/** Lands from larger to its size with the style's spring — the "slam". */
export function Slam({ children, delay = 0, from = 1.6 }: { children: React.ReactNode; delay?: number; from?: number }) {
  const frame = styledFrame(useCurrentFrame(), useLook().style);
  const { fps } = useVideoConfig();
  const { style } = useLook();
  const s = spring({ frame: frame - delay, fps, config: style.spring });
  const scale = interpolate(s, [0, 1], [from, 1]);
  const opacity = interpolate(frame - delay, [0, 2], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  return <span style={{ display: "inline-block", transform: `scale(${scale})`, opacity }}>{children}</span>;
}

/** Letter spacing opens from tight to wide — or closes, with `reverse`. */
export function TrackIn({
  children,
  delay = 0,
  from = 0.6,
  to,
  duration,
}: {
  children: React.ReactNode;
  delay?: number;
  from?: number;
  to?: number;
  duration?: number;
}) {
  const frame = styledFrame(useCurrentFrame(), useLook().style);
  const { fps } = useVideoConfig();
  const { style } = useLook();
  const target = to ?? style.fonts.display.tracking;
  const p = ramp(frame, delay, duration ?? Math.round(style.beat * fps * 2.4), style.ease.out);
  const opacity = ramp(frame, delay, 6);
  return <span style={{ display: "inline-block", letterSpacing: `${from + (target - from) * p}em`, opacity }}>{children}</span>;
}

/** Characters appear at `cps` per second behind a block cursor. */
export function Typewriter({ text, delay = 0, cps = 24, cursor = true }: { text: string; delay?: number; cps?: number; cursor?: boolean }) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const { style } = useLook();
  const shown = Math.max(0, Math.min(text.length, Math.floor(((frame - delay) / fps) * cps)));
  const blinkOn = Math.floor(frame / (fps / 2)) % 2 === 0 || shown < text.length;
  return (
    <span>
      {text.slice(0, shown)}
      {cursor && frame >= delay && (
        <span style={{ display: "inline-block", width: "0.55em", height: "1em", verticalAlign: "-0.12em", marginLeft: "0.06em", background: blinkOn ? style.colors.accent : "transparent" }} />
      )}
    </span>
  );
}

/**
 * The same word stacked: outlined copies, one filled. A typographic echo for
 * a single key word.
 */
export function Echo({ word, copies = 5, delay = 0, filled = 2, size }: { word: string; copies?: number; delay?: number; filled?: number; size: number }) {
  const frame = styledFrame(useCurrentFrame(), useLook().style);
  const { fps } = useVideoConfig();
  const { style } = useLook();
  return (
    <div style={{ display: "flex", flexDirection: "column", lineHeight: 0.86 }}>
      {Array.from({ length: copies }, (_, i) => {
        const p = ramp(frame, delay + i * 3, Math.round(style.beat * fps), style.ease.out);
        const solid = i === filled;
        return (
          <div
            key={i}
            style={{
              fontSize: size,
              color: solid ? style.colors.accent : "transparent",
              WebkitTextStroke: solid ? undefined : `2px ${style.colors.ink}`,
              opacity: solid ? p : p * (0.25 + 0.75 * (1 - Math.abs(i - filled) / copies)),
              transform: `translateY(${(1 - p) * 40}px)`,
            }}
          >
            {word}
          </div>
        );
      })}
    </div>
  );
}

/**
 * The font size at which `text` exactly fills `width` in the display face of
 * the current style, capped at `max`. Measured with the real font, which is
 * why LookProvider waits for fonts before drawing anything.
 */
export function useFitSize(text: string, width: number, max = 9999): number {
  const { style, fonts } = useLook();
  const role = style.fonts.display;
  const { fontSize } = fitText({
    text,
    withinWidth: width,
    fontFamily: fonts.display,
    fontWeight: role.weight,
    letterSpacing: `${role.tracking}em`,
    textTransform: role.uppercase ? "uppercase" : undefined,
    validateFontIsLoaded: true,
  });
  return Math.min(max, Math.floor(fontSize));
}

import React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { ramp } from "../lib/motion";
import { useLook } from "./look";

/**
 * A block of colour that sweeps across the frame, covers it and uncovers it.
 * Cut the content underneath at `at` (the moment the frame is covered) and the
 * change of scene is hidden inside the sweep.
 *
 *   <Sequence durationInFrames={cut}>…scene A…</Sequence>
 *   <Sequence from={cut}>…scene B…</Sequence>
 *   <BlockWipe at={cut} />
 */
export function BlockWipe({
  at,
  duration = 16,
  direction = "right",
  color,
  bands = 1,
}: {
  /** Frame when the screen is fully covered — put the cut here. */
  at: number;
  /** Frames for covering, and again for uncovering. */
  duration?: number;
  direction?: "right" | "left" | "up" | "down";
  color?: string;
  /** Several staggered bands instead of one block. */
  bands?: number;
}) {
  const frame = useCurrentFrame();
  const { style } = useLook();
  if (frame < at - duration || frame > at + duration + bands * 2) return null;
  const horizontal = direction === "right" || direction === "left";
  return (
    <AbsoluteFill style={{ pointerEvents: "none", flexDirection: horizontal ? "column" : "row" }}>
      {Array.from({ length: bands }, (_, i) => {
        const lag = i * 2;
        const cover = ramp(frame, at - duration + lag, duration, style.ease.inOut);
        const uncover = ramp(frame, at + lag, duration, style.ease.inOut);
        // Grows from the leading edge, then shrinks towards the trailing edge.
        const start = uncover * 100;
        const end = cover * 100;
        const forward = direction === "right" || direction === "down";
        const from = forward ? start : 100 - end;
        const size = Math.max(0, end - start);
        return (
          <div key={i} style={{ position: "relative", flex: 1 }}>
            <div
              style={{
                position: "absolute",
                background: color ?? style.colors.accent,
                ...(horizontal ? { top: 0, bottom: 0, left: `${from}%`, width: `${size}%` } : { left: 0, right: 0, top: `${from}%`, height: `${size}%` }),
              }}
            />
          </div>
        );
      })}
    </AbsoluteFill>
  );
}

import React from "react";
import { AbsoluteFill, Img, OffthreadVideo, staticFile, useCurrentFrame, useVideoConfig } from "remotion";
import { CaptionTrack, type CaptionMode, type CaptionTimeline } from "../components/captions";
import { LookProvider, useDisplayType, useLook, useMonoType } from "../components/look";
import { Corners, Stage } from "../components/stage";
import { MaskLine } from "../components/type";
import { mix, ramp, sec } from "../lib/motion";
import sample from "../../public/data/captions-sample.json";

/**
 * Captions for a vertical video. Three grounds:
 *   video   — your footage (public/…mp4), captions burnt on top
 *   image   — a still with a slow push-in
 *   graphic — no footage: chapter numbers and titles carry the picture
 *
 * Captions sit between 55% and 72% of the height: above the caption and
 * buttons that Reels, TikTok and Shorts draw over the bottom of the frame.
 * The timeline comes from the captions-explainer skill (srt_to_timeline.py).
 */

export type Chapter = { at: number; title: string };

export type CaptionsProps = {
  style: string;
  background: { type: "video" | "image" | "graphic"; src?: string };
  timeline: CaptionTimeline;
  chapters: Chapter[];
  mode: CaptionMode;
  label: string;
};

const resolve = (src: string) => (/^(https?:|data:)/.test(src) ? src : staticFile(src));

function Chapters({ chapters }: { chapters: Chapter[] }) {
  const frame = useCurrentFrame();
  const { fps, width, durationInFrames } = useVideoConfig();
  const { style } = useLook();
  const display = useDisplayType();
  const starts = chapters.map((c) => sec(c.at, fps));
  const index = Math.max(0, starts.filter((s) => s <= frame).length - 1);
  const chapter = chapters[index];
  if (!chapter) return null;
  const local = frame - starts[index];
  const end = (starts[index + 1] ?? durationInFrames + 10) - starts[index];
  const number = String(index + 1).padStart(2, "0");
  const grow = ramp(local, 0, 20, style.ease.out);
  return (
    <AbsoluteFill style={{ padding: "220px 80px 0" }}>
      <div
        style={{
          ...display,
          fontSize: 520,
          lineHeight: 0.8,
          color: "transparent",
          WebkitTextStroke: `3px ${style.colors.accent}`,
          transform: `translateX(${mix(-60, 0, grow)}px)`,
          opacity: grow * (local > end - 8 ? Math.max(0, (end - local) / 8) : 1),
        }}
      >
        {number}
      </div>
      <div key={index} style={{ ...display, fontSize: 92, marginTop: 40, width: width - 160 }}>
        <MaskLine delay={starts[index] + 6} exitAt={starts[index] + end - 10}>
          {chapter.title}
        </MaskLine>
      </div>
    </AbsoluteFill>
  );
}

/**
 * A row of level bars that moves while a word is being spoken — the voice
 * made visible when there is no footage.
 */
function VoiceMeter({ timeline }: { timeline: CaptionTimeline }) {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();
  const { style } = useLook();
  const t = frame / fps;
  const words = timeline.pages.flatMap((p) => p.words);
  const speaking = words.some((w) => t >= w.start && t < w.end) ? 1 : 0;
  const bars = 36;
  const span = width - 140;
  return (
    <div style={{ position: "absolute", left: 70, width: span, top: "44%", height: 120, display: "flex", alignItems: "center", gap: 8 }}>
      {Array.from({ length: bars }, (_, i) => {
        const wave = 0.5 + 0.5 * Math.sin(frame * 0.55 + i * 1.7) * Math.sin(frame * 0.23 + i * 0.6);
        const h = 6 + speaking * wave * 110 * (0.35 + 0.65 * Math.sin((Math.PI * (i + 0.5)) / bars));
        return <div key={i} style={{ flex: 1, height: h, borderRadius: 3, background: i % 6 === 0 ? style.colors.accent : style.colors.ink, opacity: i % 6 === 0 ? 1 : 0.32 }} />;
      })}
    </div>
  );
}

function Ground({ background }: { background: CaptionsProps["background"] }) {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  const { style } = useLook();
  if (background.type === "video" && background.src) {
    return <OffthreadVideo src={resolve(background.src)} style={{ width: "100%", height: "100%", objectFit: "cover" }} muted={false} />;
  }
  if (background.type === "image" && background.src) {
    const scale = 1.04 + (frame / durationInFrames) * 0.1;
    return <Img src={resolve(background.src)} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${scale})` }} />;
  }
  return <AbsoluteFill style={{ background: style.colors.ground }} />;
}

function Layout({ background, timeline, chapters, mode, label }: Omit<CaptionsProps, "style">) {
  const { height } = useVideoConfig();
  const { style } = useLook();
  const mono = useMonoType();
  const footage = background.type !== "graphic";
  return (
    <Stage grain={footage ? 0.04 : undefined}>
      <Ground background={background} />
      {footage && (
        <AbsoluteFill style={{ background: `linear-gradient(180deg, transparent 35%, ${style.colors.ground}cc 75%, ${style.colors.ground} 100%)` }} />
      )}
      {!footage && <Chapters chapters={chapters} />}
      {!footage && <VoiceMeter timeline={timeline} />}
      <AbsoluteFill style={{ top: height * 0.55, height: height * 0.17, bottom: "auto", alignItems: "center", justifyContent: "center", padding: "0 150px 0 70px" }}>
        {/* Right padding keeps captions clear of the platform's buttons. */}
        <CaptionTrack timeline={timeline} mode={mode} size={90} maxWidth={860} />
      </AbsoluteFill>
      <Corners tl={label} tr="{tc}" inset={70} size={22} />
      <div style={{ ...mono, position: "absolute", left: 70, top: height * 0.55 - 50, fontSize: 20, display: "flex", alignItems: "center", gap: 12 }}>
        <span style={{ width: 12, height: 12, borderRadius: 6, background: style.colors.accent }} />
        REC
      </div>
    </Stage>
  );
}

export function Captions({ style, ...rest }: CaptionsProps) {
  return (
    <LookProvider styleId={style}>
      <Layout {...rest} />
    </LookProvider>
  );
}

export const captionsDefaults: CaptionsProps = {
  style: "signal",
  background: { type: "graphic" },
  timeline: sample as CaptionTimeline,
  chapters: [
    { at: 0, title: "Зачем субтитры" },
    { at: 4.6, title: "Как их сделать" },
  ],
  mode: "pop",
  label: "Explainer — 9:16",
};

import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from "remotion";
import { Bars, Counter, Line, type ChartSpec, type Delta } from "../components/charts";
import { LookProvider, useDisplayType, useLook, useMonoType, useTextType } from "../components/look";
import { Corners, GridLines, Stage } from "../components/stage";
