import React from "react";
import { AbsoluteFill, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { evolvePath } from "@remotion/paths";
import { LookProvider, useDisplayType, useLook, useMonoType } from "../components/look";
import { Corners, Stage } from "../components/stage";
import { MaskLine, TrackIn } from "../components/type";
import { mix, ramp } from "../lib/motion";
import brandMark from "../../public/data/logo-sample.json";

/**
 * A logo sting: registration marks draw in, the logo's outlines trace
 * themselves, the fills land, the mark slides aside and the name rises next
 * to it. About four seconds — the length of an intro or an outro.
 *
 * `logo` comes from the logo-sting skill's svg_prepare.py, which turns an
 * SVG's shapes into plain paths with their fills.
 */

export type LogoPath = { d: string; fill: string | null; stroke: string | null; strokeWidth: number };
export type LogoData = { viewBox: [number, number, number, number]; paths: LogoPath[] };

export type LogoStingProps = {
  style: string;
  logo: LogoData;
  name: string;
  tagline: string;
  /** Use the style's accent for fills instead of the logo's own colours. */
  monochrome: boolean;
};

function Marks({ size }: { size: number }) {
  const frame = useCurrentFrame();
  const { style } = useLook();
  const p = ramp(frame, 0, 22, style.ease.out);
  const out = ramp(frame, 40, 14, style.ease.in);
  const reach = size * 0.9 * p;
  const line = (w: number, h: number, x: number, y: number) => (
    <div style={{ position: "absolute", left: x, top: y, width: w, height: h, background: style.colors.line, opacity: 1 - out }} />
  );
  return (
    <>
      {line(reach * 2, 1, -reach, 0)}
      {line(1, reach * 2, 0, -reach)}
      <div style={{ position: "absolute", left: -size * 0.6, top: -size * 0.6, width: size * 1.2, height: size * 1.2, border: `1px solid ${style.colors.line}`, borderRadius: "50%", transform: `scale(${p})`, opacity: 1 - out }} />
    </>
  );
}

function Mark({ logo, size, monochrome }: { logo: LogoData; size: number; monochrome: boolean }) {
  const frame = useCurrentFrame();
  const { style } = useLook();
  const [, , vw, vh] = logo.viewBox;
  const unit = vw / size; // viewBox units per pixel
  return (
    <svg width={size} height={(size * vh) / vw} viewBox={logo.viewBox.join(" ")} style={{ overflow: "visible" }}>
      {logo.paths.map((path, i) => {
        // Filled shapes trace first; outline-only shapes are drawn on top once the fills are in.
        const outlineOnly = !path.fill && !monochrome;
        const draw = ramp(frame, outlineOnly ? 40 + i * 4 : 8 + i * 6, outlineOnly ? 18 : 26, style.ease.inOut);
        const fill = ramp(frame, 30 + i * 4, 12, style.ease.out);
        const evolved = evolvePath(draw, path.d);
        const colour = monochrome ? (i === 0 ? style.colors.accent : style.colors.onAccent) : path.fill ?? style.colors.ink;
        return (
          <g key={i}>
            {(path.fill || monochrome) && <path d={path.d} fill={colour} opacity={fill} />}
            <path
              d={path.d}
              fill="none"
              stroke={path.stroke && !monochrome ? path.stroke : style.colors.accent}
              strokeWidth={path.stroke ? path.strokeWidth : unit * 3}
              strokeDasharray={evolved.strokeDasharray}
              strokeDashoffset={evolved.strokeDashoffset}
              opacity={path.stroke ? 1 : 1 - fill}
            />
          </g>
        );
      })}
    </svg>
  );
}

function Sting({ logo, name, tagline, monochrome }: Omit<LogoStingProps, "style">) {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();
  const { style } = useLook();
  const display = useDisplayType();
  const mono = useMonoType();
  const size = 300;
  const slide = spring({ frame: frame - 46, fps, config: style.spring });
  const pop = spring({ frame: frame - 30, fps, config: { damping: 12, stiffness: 160 } });
  const nameSize = 176;
  // The mark starts centred, then moves left to make room for the name.
  const shift = mix(0, -Math.min(width * 0.24, name.length * nameSize * 0.28), slide);
  const exit = ramp(frame, fps * 4.4, 10, style.ease.in);
  return (
    <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", opacity: 1 - exit }}>
      <div style={{ position: "relative", transform: `translateX(${shift}px)` }}>
        <div style={{ position: "absolute", left: size / 2, top: size / 2 }}>
          <Marks size={size} />
        </div>
        <div style={{ transform: `scale(${mix(0.92, 1, pop)})` }}>
          <Mark logo={logo} size={size} monochrome={monochrome} />
        </div>
        <div style={{ position: "absolute", left: size + 64, top: size / 2, transform: "translateY(-58%)", whiteSpace: "nowrap" }}>
          <div style={{ ...display, fontSize: nameSize, lineHeight: 1 }}>
            {name.split("").map((char, i) => (
              <MaskLine key={i} delay={52 + i * 2}>
                {char === " " ? " " : char}
              </MaskLine>
            ))}
          </div>
          <div style={{ ...mono, fontSize: 28, marginTop: 22, color: style.colors.accent }}>
            <TrackIn delay={70} from={0.6} to={0.16}>
              {tagline}
            </TrackIn>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

export function LogoSting({ style, ...rest }: LogoStingProps) {
  return (
    <LookProvider styleId={style}>
      <Stage>
        <Sting {...rest} />
        <Corners tl="Logo — Sting" tr="{tc}" inset={56} size={18} />
      </Stage>
    </LookProvider>
  );
}

export const logoStingDefaults: LogoStingProps = {
  style: "signal",
  logo: brandMark as LogoData,
  name: "Insider",
  tagline: "Motion Studio",
  monochrome: false,
};

import React from "react";
import { AbsoluteFill, Sequence, staticFile, useCurrentFrame, useVideoConfig } from "remotion";
import { BrowserFrame, Callout, Cursor, Screen, useZoom, type CursorStop, type Zoom } from "../components/device";
import { LookProvider, useDisplayType, useLook, useMonoType } from "../components/look";
import { Corners, Stage } from "../components/stage";
import { MaskLine, Marker } from "../components/type";
import { BlockWipe } from "../components/wipe";
import { mix, ramp, sec } from "../lib/motion";

/**
 * A product promo from real screenshots. One browser window stays on screen;
 * each shot swaps the page inside it behind a colour wipe, the cursor shows
 * what to click, the camera pushes in on the part that matters, and a callout
 * names it. Ends on a card with the address.
 *
 * Screenshots go in public/ (e.g. public/shots/home.png). Times in a shot are
 * seconds from the start of the video. Points — cursor stops, zoom centre,
 * callout — are fractions of the screenshot (0,0 top left; 1,1 bottom right);
 * the cursor and callouts follow the camera when it zooms.
 */

export type PromoShot = {
  src: string;
  url: string;
  /** Start of the shot in seconds. */
  at: number;
  /** Small label over the window: "01 — Главная". */
  label: string;
  cursor: CursorStop[];
  clicks: number[];
  zoom?: Zoom;
  callout?: { x: number; y: number; text: string; at: number; side?: "left" | "right" };
};

export type ProductPromoProps = {
  style: string;
  brand: string;
  shots: PromoShot[];
  end: { at: number; title: string; marked: string; url: string };
};

const WINDOW_W = 1360;
const SCREEN_H = Math.round((WINDOW_W * 900) / 1440);

const resolve = (src: string) => (/^(https?:|data:)/.test(src) ? src : staticFile(src));

function Window({ shots, endAt }: { shots: PromoShot[]; endAt: number }) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const { style } = useLook();
  const mono = useMonoType();
  const enter = ramp(frame, 0, Math.round(fps * 1.1), style.ease.out);
  const leave = ramp(frame, endAt - 14, 14, style.ease.in);
  const starts = shots.map((shot) => sec(shot.at, fps));
  const current = Math.max(0, starts.filter((s) => s <= frame).length - 1);
  const shot = shots[current];
  const shotStart = starts[current];
  const shotEnd = starts[current + 1] ?? endAt;
  // A slow turn across each shot gives the flat screenshot some depth.
  const drift = (frame - shotStart) / Math.max(1, shotEnd - shotStart);
  const rotateY = mix(-5, 5, drift) * (current % 2 ? -1 : 1);
  const rotateX = mix(26, 4, enter) + leave * 10;
  const lift = (1 - enter) * 340 - leave * 120;
  const scale = mix(0.84, 1, enter) - leave * 0.08;
  const barH = Math.round(SCREEN_H * 0.055);
  const camera = useZoom(shot.zoom, WINDOW_W, SCREEN_H);
  const left = (width - WINDOW_W) / 2;
  const top = (height - SCREEN_H - barH) / 2 + 40;

  return (
    <AbsoluteFill style={{ perspective: 2200, opacity: 1 - leave }}>
      <div style={{ ...mono, position: "absolute", left, top: top - 64, fontSize: 22, opacity: enter }}>
        <MaskLine key={current} delay={shotStart + 4}>
          <span style={{ color: style.colors.accent }}>{String(current + 1).padStart(2, "0")}</span>
          {"  "}
          {shot.label}
        </MaskLine>
      </div>
      <div
        style={{
          position: "absolute",
          left,
          top,
          transform: `translateY(${lift}px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale(${scale})`,
          transformOrigin: "50% 100%",
        }}
      >
        <BrowserFrame url={shot.url} width={WINDOW_W} height={SCREEN_H}>
          <Screen src={resolve(shot.src)} zoom={shot.zoom} width={WINDOW_W} height={SCREEN_H} />
          <Cursor stops={shot.cursor} clicks={shot.clicks} width={WINDOW_W} height={SCREEN_H} map={camera.map} />
        </BrowserFrame>
        {shot.callout && (
          <div style={{ position: "absolute", left: 0, top: barH, width: WINDOW_W, height: SCREEN_H }}>
            <Callout {...shot.callout} {...camera.map(shot.callout.x, shot.callout.y)} width={WINDOW_W} height={SCREEN_H} />
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
}

function EndCard({ title, marked, url }: { title: string; marked: string; url: string }) {
  const frame = useCurrentFrame();
  const { style } = useLook();
  const display = useDisplayType();
  const mono = useMonoType();
  return (
    <AbsoluteFill style={{ justifyContent: "center", padding: "0 160px" }}>
      <div style={{ ...display, fontSize: 150 }}>
        <div>
          <MaskLine delay={4}>{title}</MaskLine>
        </div>
        <div style={{ marginTop: 10 }}>
          <MaskLine delay={9}>
            <Marker delay={12}>{marked}</Marker>
          </MaskLine>
        </div>
      </div>
      <div style={{ ...mono, fontSize: 30, marginTop: 64, color: style.colors.ink, textTransform: "none", letterSpacing: "0.04em", opacity: ramp(frame, 22, 10) }}>
        → {url}
      </div>
    </AbsoluteFill>
  );
}

function Promo({ brand, shots, end }: Omit<ProductPromoProps, "style">) {
  const { fps, durationInFrames } = useVideoConfig();
  const endAt = sec(end.at, fps);
  const starts = shots.map((shot) => sec(shot.at, fps));
  return (
    <Stage>
      <Sequence durationInFrames={endAt} layout="none">
        <Window shots={shots} endAt={endAt} />
      </Sequence>
      <Sequence from={endAt} durationInFrames={durationInFrames - endAt} layout="none">
        <EndCard title={end.title} marked={end.marked} url={end.url} />
      </Sequence>
      {starts.slice(1).map((s) => (
        <BlockWipe key={s} at={s} duration={12} bands={4} />
      ))}
      <Corners bl={brand} tr="{tc}" inset={56} size={18} />
    </Stage>
  );
}

export function ProductPromo({ style, ...rest }: ProductPromoProps) {
  return (
    <LookProvider styleId={style}>
      <Promo {...rest} />
    </LookProvider>
  );
}

