/**
 * The same two lines in every style of the library, one after another. Used
 * by the motion-director skill to let someone choose a style by looking, and
 * to check a new style against the others.
 */

export type StyleBoardProps = { first: string; second: string; seconds: number };

function Panel({ first, second, index, total }: { first: string; second: string; index: number; total: number }) {
  const { width } = useVideoConfig();
  const { style } = useLook();
  const display = useDisplayType();
  const mono = useMonoType();
  const size = useFitSize(first.length > second.length ? first : second, width * 0.72, 200);
  return (
    <Stage>
      <GridLines columns={12} inset={72} duration={14} />
      <AbsoluteFill style={{ justifyContent: "center", padding: "0 140px" }}>
        <div style={{ ...mono, fontSize: 22, marginBottom: 36 }}>
          {String(index + 1).padStart(2, "0")} / {String(total).padStart(2, "0")} — {style.name}
        </div>
        <div style={{ ...display, fontSize: size }}>
          <div>
            <MaskLine delay={2} duration={10}>{first}</MaskLine>
          </div>
          <div>
            <MaskLine delay={5} duration={10}>
              <Marker delay={9} duration={8}>
                {second}
              </Marker>
            </MaskLine>
          </div>
        </div>
      </AbsoluteFill>
      <Corners tl="Style library" tr="{tc}" inset={72} size={18} />
    </Stage>
  );
}

export function StyleBoard({ first, second, seconds }: StyleBoardProps) {
  const { fps } = useVideoConfig();
  const length = Math.round(seconds * fps);
  return (
    <>
      {STYLE_IDS.map((id, i) => (
        <Sequence key={id} from={i * length} durationInFrames={length}>
          <LookProvider styleId={id}>
            <Panel first={first} second={second} index={i} total={STYLE_IDS.length} />
          </LookProvider>
        </Sequence>
      ))}
    </>
  );
}

export const styleBoardDefaults: StyleBoardProps = { first: "Один текст.", second: "Восемь стилей.", seconds: 1 };

import { registerRoot } from "remotion";
import { Root } from "./Root";

registerRoot(Root);

import { Easing, interpolate } from "remotion";
import type { Bezier, Style } from "../styles/styles";

/**
 * Small, boring helpers that keep compositions readable. Times in props are
 * seconds (people think in seconds); everything inside is frames.
 */

export const bezier = (curve: Bezier) => Easing.bezier(...curve);

/** Seconds → frames, rounded so cuts land on whole frames. */
export const sec = (seconds: number, fps: number) => Math.round(seconds * fps);

/**
 * 0 → 1 over `duration` frames starting at `start`, eased and clamped.
 * The workhorse: almost every move in the library is `ramp` + interpolate.
 */
export function ramp(frame: number, start: number, duration: number, curve: Bezier = [0.16, 1, 0.3, 1]): number {
  if (duration <= 0) return frame >= start ? 1 : 0;
  return interpolate(frame, [start, start + duration], [0, 1], {
    easing: bezier(curve),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
}

/** In, hold, out: 0 → 1 → 0. For things that appear and leave. */
export function inOut(frame: number, start: number, end: number, fade: number, curve: Bezier): number {
  return Math.min(ramp(frame, start, fade, curve), 1 - ramp(frame, end - fade, fade, curve));
}

export const mix = (a: number, b: number, t: number) => a + (b - a) * t;

/** Holds every second frame when the style animates on twos. */
export const styledFrame = (frame: number, style: Style) => (style.onTwos ? frame - (frame % 2) : frame);

/** Beat times in seconds → frames. Beats come from the beat-sync skill. */
export const beatFrames = (beats: number[] | undefined, fps: number) => (beats ?? []).map((b) => sec(b, fps));

/**
 * 1 on a beat, falling to 0 over `decay` frames. Drive scale, brightness or a
 * flash with it so the picture breathes with the music.
 */
export function pulse(frame: number, beats: number[], decay = 8): number {
  let value = 0;
  for (const beat of beats) {
    const age = frame - beat;
    if (age >= 0 && age < decay) value = Math.max(value, 1 - age / decay);
  }
  return value;
}

/** The beat at or before `frame`, for cutting on the beat. */
export function lastBeat(frame: number, beats: number[]): number {
  let found = -1;
  for (const beat of beats) if (beat <= frame) found = beat;
  return found;
}

/** Snaps a planned cut to the nearest beat within `tolerance` frames. */
export function snapToBeat(frame: number, beats: number[], tolerance = 4): number {
  let best = frame;
  let distance = tolerance + 1;
  for (const beat of beats) {
    const d = Math.abs(beat - frame);
    if (d < distance) {
      best = beat;
      distance = d;
    }
  }
  return best;
}

/** Deterministic pseudo-random in [0, 1) — never Math.random() in a render. */
export function seeded(seed: number): number {
  const x = Math.sin(seed * 12.9898 + 78.233) * 43758.5453;
  return x - Math.floor(x);
}

import { loadFont as geologica } from "@remotion/google-fonts/Geologica";
import { loadFont as golosText } from "@remotion/google-fonts/GolosText";
import { loadFont as ibmPlexMono } from "@remotion/google-fonts/IBMPlexMono";
import { loadFont as interTight } from "@remotion/google-fonts/InterTight";
import { loadFont as jetBrainsMono } from "@remotion/google-fonts/JetBrainsMono";
import { loadFont as manrope } from "@remotion/google-fonts/Manrope";
import { loadFont as onest } from "@remotion/google-fonts/Onest";
import { loadFont as playfairDisplay } from "@remotion/google-fonts/PlayfairDisplay";
import { loadFont as robotoCondensed } from "@remotion/google-fonts/RobotoCondensed";
import { loadFont as robotoMono } from "@remotion/google-fonts/RobotoMono";
import { loadFont as rubik } from "@remotion/google-fonts/Rubik";
import { loadFont as spectral } from "@remotion/google-fonts/Spectral";
import { loadFont as unbounded } from "@remotion/google-fonts/Unbounded";
import type { FontFamilyId, FontRole, Style } from "./styles";

/**
 * Fonts come from Google Fonts at render time (the renderer needs internet the
 * first time). Only the weights a style uses are fetched, in Latin and
 * Cyrillic. To use a local font instead, put the file in public/fonts and load
 * it with @remotion/fonts — see the motion-director skill, references/fonts.md.
 */

// Each loader is typed with its own weight list; they share one call shape.
type Loader = (
  style?: "normal" | "italic",
  options?: { weights?: string[]; subsets?: string[] },
) => { fontFamily: string; waitUntilDone: () => Promise<unknown> };

const LOADERS: Record<FontFamilyId, Loader> = {
  Geologica: geologica as unknown as Loader,
  GolosText: golosText as unknown as Loader,
  IBMPlexMono: ibmPlexMono as unknown as Loader,
  InterTight: interTight as unknown as Loader,
  JetBrainsMono: jetBrainsMono as unknown as Loader,
  Manrope: manrope as unknown as Loader,
  Onest: onest as unknown as Loader,
  PlayfairDisplay: playfairDisplay as unknown as Loader,
  RobotoCondensed: robotoCondensed as unknown as Loader,
  RobotoMono: robotoMono as unknown as Loader,
  Rubik: rubik as unknown as Loader,
  Spectral: spectral as unknown as Loader,
  Unbounded: unbounded as unknown as Loader,
};

const loaded = new Map<string, { fontFamily: string; done: Promise<unknown> }>();

function load(role: FontRole, extraWeights: number[] = []) {
  const weights = [...new Set([role.weight, ...extraWeights])].map(String);
  const key = `${role.family}:${role.italic ? "i" : "n"}:${weights.join(",")}`;
  const hit = loaded.get(key);
  if (hit) return hit;
  const font = LOADERS[role.family](role.italic ? "italic" : "normal", {
    weights,
    subsets: ["latin", "cyrillic"],
  });
  const entry = { fontFamily: font.fontFamily, done: font.waitUntilDone() };
  loaded.set(key, entry);
  return entry;
}

export type StyleFonts = { display: string; text: string; mono: string };

/**
 * Starts loading a style's three faces. Returns their CSS font-family values
 * and a promise that settles when the files are in — text is measured (for
 * fitting words to the frame) only after that.
 */
export function loadStyleFonts(style: Style): { fonts: StyleFonts; ready: Promise<unknown> } {
  const display = load(style.fonts.display);
  const text = load(style.fonts.text, style.fonts.text.weight === 700 ? [] : [700]);
  const mono = load(style.fonts.mono);
  return {
    fonts: { display: display.fontFamily, text: text.fontFamily, mono: mono.fontFamily },
    ready: Promise.all([display.done, text.done, mono.done]),
  };
}

/**
 * The style library. A style is a complete set of decisions — colours, type,
 * easing, texture and how things are allowed to move — so a video made in one
 * style looks designed rather than assembled. Pick one per video; do not mix.
 *
 * Every family here has Cyrillic glyphs on Google Fonts, so Russian and
 * Ukrainian text renders in the intended face, not in a fallback.
 *
 * Descriptions for choosing a style live in the motion-director skill:
 * references/styles.md.
 */

export type Bezier = [number, number, number, number];

export type StyleId =
  | "signal"
  | "swiss-grid"
  | "editorial"
  | "terminal"
  | "bold-kinetic"
  | "data-noir"
  | "print-riso"
  | "quiet-line";

export type FontRole = {
  /** Google Fonts family, exactly as loadFont() exports it (see fonts.ts). */
  family: FontFamilyId;
  weight: number;
  /** Letter spacing in em at display sizes. */
  tracking: number;
  /** Line height at display sizes. */
  leading: number;
  italic?: boolean;
  uppercase?: boolean;
};

export type FontFamilyId =
  | "Geologica"
  | "GolosText"
  | "JetBrainsMono"
  | "InterTight"
  | "PlayfairDisplay"
  | "IBMPlexMono"
  | "Unbounded"
  | "Onest"
  | "RobotoCondensed"
  | "RobotoMono"
  | "Rubik"
  | "Spectral"
  | "Manrope";

export type Style = {
  id: StyleId;
  name: string;
  colors: {
    ground: string;
    /** A second ground for panels and cards. */
    panel: string;
    ink: string;
    muted: string;
    line: string;
    accent: string;
    /** Text set on the accent colour. */
    onAccent: string;
    /** Second accent, used sparingly: negative values, a second series. */
    accent2: string;
  };
  fonts: { display: FontRole; text: FontRole; mono: FontRole };
  ease: { out: Bezier; inOut: Bezier; in: Bezier };
  /** For spring() — damping high means no wobble. */
  spring: { damping: number; stiffness: number; mass: number };
  /** Base duration of one move, in seconds. Everything else scales from it. */
  beat: number;
  texture: { grain: number; scanlines: boolean; misregister: number };
  /** Animate on twos: hold every second frame, for a printed, hand-made feel. */
  onTwos: boolean;
  radius: number;
