      "parameters": {
        "jsCode": "// Guard Out: проверяет ответ модели до отправки клиенту.\n// ---- shared text helpers (inlined into Code nodes by the builder) ----\nconst STOP = new Set(('и в во не что он на я с со как а то все она так его но да ты к у же вы за бы по только ее мне было вот от меня еще нет о из ему теперь когда даже ну вдруг ли если уже или ни быть был него до вас нибудь опять уж вам ведь там потом себя ничего ей может они тут где есть надо ней для мы тебя их чем была сам чтоб без будто чего раз тоже себе под будет ж тогда кто этот того потому этого какой совсем ним здесь этом один почти мой тем чтобы нее сейчас были куда зачем всех никогда можно при наконец два об другой хоть после над больше тот через эти нас про всего них какая много разве три эту моя впрочем хорошо свою этой перед иногда лучше чуть том нельзя такой им более всегда конечно всю между это мой мою мое здравствуйте добрый день привет пожалуйста подскажите скажите хочу хотел хотела можно ли вы ваш ваша ваши the a an and or of to in on for is are be it this that with as at by from i you we my our your me do does how what can could please hi hello').split(' '));\n\nfunction stem(word) {\n  let w = word.toLowerCase().replace(/ё/g, 'е');\n  if (/^[a-z]+$/.test(w)) return w.replace(/(ing|ed|es|s)$/, '').slice(0, 7);\n  w = w.replace(/(ями|ами|иями|ией|ией|ого|ему|ому|ыми|ими|его|ая|яя|ое|ее|ие|ые|ой|ей|ий|ый|ов|ев|ам|ям|ах|ях|ом|ем|ую|юю|ть|ти|ешь|ет|ем|ете|ют|ут|ит|им|ите|ат|ят|ла|ло|ли|ся|сь|а|я|о|е|и|ы|у|ю|ь|й)$/, '');\n  return w.slice(0, 6);\n}\n\nfunction terms(text) {\n  return (String(text).toLowerCase().match(/[\\p{L}\\p{N}]+/gu) || [])\n    .filter((w) => w.length > 1 && !STOP.has(w))\n    .map(stem)\n    .filter((w) => w.length > 1);\n}\n\nfunction escapeHtml(text) {\n  return String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n}\n\nfunction sheetRows(values) {\n  const [head = [], ...rows] = values || [];\n  const keys = head.map((h) => String(h).trim().toLowerCase());\n  return rows.map((r, i) => Object.fromEntries([['_row', i + 2], ...keys.map((k, j) => [k, String(r[j] ?? '').trim()])]));\n}\n\nconst config = $('Config').first().json.config;\nconst g = $('Guard In').first().json;\nconst result = $input.first().json;\nconst store = $getWorkflowStaticData('global');\nconst now = Date.now();\n\nconst steps = Array.isArray(result.intermediateSteps) ? result.intermediateSteps : [];\nconst tools = steps.map((s) => ({ name: s.action?.tool ?? '', input: s.action?.toolInput ?? {} }));\nconst used = new Set(tools.map((t) => t.name));\nconst flags = [...(g.flags || [])];\n\nfunction observation(name) {\n  const step = [...steps].reverse().find((s) => s.action?.tool === name);\n  if (!step) return null;\n  let o = step.observation;\n  if (typeof o === 'string') {\n    try { o = JSON.parse(o); } catch { return { text: o }; }\n  }\n  if (Array.isArray(o)) o = o[0]?.json ?? o[0];\n  if (o && typeof o.response === 'string') {\n    try { o = JSON.parse(o.response); } catch { /* keep */ }\n  }\n  return o;\n}\n\nlet reply = String(result.output ?? '').trim();\nlet alert_html = '';\n// Передача засчитывается, только если команда действительно получила уведомление.\nconst handoffOk = used.has('handoff_to_human') && observation('handoff_to_human')?.ok !== false;\nlet handoff = handoffOk;\nconst safe = `Этот вопрос лучше решит менеджер — я передал ему ваш запрос. Ответим в рабочее время: ${config.support_hours}.`;\n\nfunction forceHandoff(reason) {\n  handoff = true;\n  const c = g.customer || {};\n  alert_html = [\n    `<b>⚠️ ${reason}</b>`,\n    `Канал: ${g.channel === 'telegram' ? 'Telegram' : 'сайт'} · <code>${escapeHtml(g.session_id)}</code>`,\n    c.name && `Имя: ${escapeHtml(c.name)}`,\n    c.email && `Email: ${escapeHtml(c.email)}`,\n    c.phone && `Телефон: ${escapeHtml(c.phone)}`,\n    c.telegram && `Telegram: ${escapeHtml(c.telegram)}`,\n    '',\n    `<blockquote>${escapeHtml(g.text)}</blockquote>`,\n  ].filter(Boolean).join('\\n');\n}\n\nif (!reply) {\n  flags.push('empty_reply');\n  reply = safe;\n  if (!handoffOk) forceHandoff('Агент не смог ответить');\n}\nif (config.canary && reply.includes(config.canary)) {\n  flags.push('prompt_leak');\n  reply = 'Я не могу этим поделиться. Чем помочь по вашему вопросу?';\n}\nconst forbidden = (config.forbidden || []).map((p) => new RegExp(p, 'iu'));\nif (forbidden.some((r) => r.test(reply))) {\n  flags.push('forbidden_promise');\n  reply = safe;\n  if (!handoffOk) forceHandoff('Агент пытался пообещать то, что решает только менеджер');\n}\nif (reply.length > 3500) {\n  reply = reply.slice(0, 3500).replace(/\\s+\\S*$/, '') + '…';\n  flags.push('reply_cut');\n}\n\nif (handoff) {\n  const s = (store.sessions = store.sessions || {});\n  const entry = (s[g.session_id] = s[g.session_id] || { hits: [], handoff_until: 0 });\n  entry.handoff_until = now + config.handoff_pause_minutes * 60000;\n}\n\n// Сбой таблицы или Telegram внутри инструмента: клиенту агент уже ответил, команде — сигнал.\nconst broken = ['search_policies', 'get_order', 'check_return', 'create_return_request', 'handoff_to_human']\n  .map((name) => [name, observation(name)])\n  .filter(([, o]) => o && o.service_error);\nif (broken.length) {\n  flags.push('service_error');\n  const lines = broken.map(([name, o]) => `${name}: ${escapeHtml(o.service_error || o.note)}`);\n  alert_html = (alert_html ? alert_html + '\\n\\n' : '') + `<b>⚠️ Ошибка инструмента</b>\\n${lines.join('\\n')}\\n<code>${escapeHtml(g.session_id)}</code>`;\n}\n\nconst ticket = observation('create_return_request');\nreturn [{ json: {\n  channel: g.channel,\n  session_id: g.session_id,\n  customer: g.customer,\n  text: g.text,\n  reply,\n  reply_html: escapeHtml(reply),\n  handoff,\n  alert_html,\n  tools,\n  flags,\n  ticket_id: ticket?.rma ?? '',\n  debug: Boolean(g.debug),\n} }];\n"
      }
