        "jsCode": "// Compose Cart Email: письмо о брошенной корзине. Первая фраза — от модели, если она прошла проверку,\n// иначе из шаблона. Цены, скидки и ссылки модель не пишет: их подставляет шаблон.\n// ---- shared text helpers (inlined into Code nodes by the builder) ----\nconst STOP = new Set(('и в во не что он на я с со как а то все она так его но да ты к у же вы за бы по только ее мне было вот от меня еще нет о из ему теперь когда даже ну вдруг ли если уже или ни быть был него до вас нибудь опять уж вам ведь там потом себя ничего ей может они тут где есть надо ней для мы тебя их чем была сам чтоб без будто чего раз тоже себе под будет ж тогда кто этот того потому этого какой совсем ним здесь этом один почти мой тем чтобы нее сейчас были куда зачем всех никогда можно при наконец два об другой хоть после над больше тот через эти нас про всего них какая много разве три эту моя впрочем хорошо свою этой перед иногда лучше чуть том нельзя такой им более всегда конечно всю между это мой мою мое здравствуйте добрый день привет пожалуйста подскажите скажите хочу хотел хотела можно ли вы ваш ваша ваши the a an and or of to in on for is are be it this that with as at by from i you we my our your me do does how what can could please hi hello').split(' '));\n\nfunction stem(word) {\n  let w = word.toLowerCase().replace(/ё/g, 'е');\n  if (/^[a-z]+$/.test(w)) return w.replace(/(ing|ed|es|s)$/, '').slice(0, 7);\n  w = w.replace(/(ями|ами|иями|ией|ией|ого|ему|ому|ыми|ими|его|ая|яя|ое|ее|ие|ые|ой|ей|ий|ый|ов|ев|ам|ям|ах|ях|ом|ем|ую|юю|ть|ти|ешь|ет|ем|ете|ют|ут|ит|им|ите|ат|ят|ла|ло|ли|ся|сь|а|я|о|е|и|ы|у|ю|ь|й)$/, '');\n  return w.slice(0, 6);\n}\n\nfunction terms(text) {\n  return (String(text).toLowerCase().match(/[\\p{L}\\p{N}]+/gu) || [])\n    .filter((w) => w.length > 1 && !STOP.has(w))\n    .map(stem)\n    .filter((w) => w.length > 1);\n}\n\nfunction escapeHtml(text) {\n  return String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n}\n\nfunction sheetRows(values) {\n  const [head = [], ...rows] = values || [];\n  const keys = head.map((h) => String(h).trim().toLowerCase());\n  return rows.map((r, i) => Object.fromEntries([['_row', i + 2], ...keys.map((k, j) => [k, String(r[j] ?? '').trim()])]));\n}\n\n// ---- HMAC-SHA256 без модулей: Code-узел n8n не даёт подключить crypto по умолчанию ----\nfunction sha256Bytes(bytes) {\n  const K = [0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2];\n  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];\n  const len = bytes.length;\n  const padded = new Uint8Array(((len + 9 + 63) >> 6) << 6);\n  padded.set(bytes);\n  padded[len] = 0x80;\n  const bits = len * 8;\n  const dv = new DataView(padded.buffer);\n  dv.setUint32(padded.length - 8, Math.floor(bits / 2 ** 32));\n  dv.setUint32(padded.length - 4, bits >>> 0);\n  const w = new Uint32Array(64);\n  const rotr = (x, n) => (x >>> n) | (x << (32 - n));\n  for (let off = 0; off < padded.length; off += 64) {\n    for (let i = 0; i < 16; i++) w[i] = dv.getUint32(off + i * 4);\n    for (let i = 16; i < 64; i++) {\n      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);\n      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);\n      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;\n    }\n    let [a, b, c, d, e, f, g, h] = H;\n    for (let i = 0; i < 64; i++) {\n      const t1 = (h + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) >>> 0;\n      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;\n      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;\n    }\n    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;\n    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;\n  }\n  const out = new Uint8Array(32);\n  H.forEach((v, i) => new DataView(out.buffer).setUint32(i * 4, v));\n  return out;\n}\n\nfunction hmacSha256Hex(key, message) {\n  const enc = (s) => new TextEncoder().encode(String(s));\n  let k = enc(key);\n  if (k.length > 64) k = sha256Bytes(k);\n  const block = new Uint8Array(64);\n  block.set(k);\n  const ipad = block.map((b) => b ^ 0x36);\n  const opad = block.map((b) => b ^ 0x5c);\n  const m = enc(message);\n  const inner = new Uint8Array(64 + m.length);\n  inner.set(ipad);\n  inner.set(m, 64);\n  const ih = sha256Bytes(inner);\n  const outer = new Uint8Array(96);\n  outer.set(opad);\n  outer.set(ih, 64);\n  return [...sha256Bytes(outer)].map((b) => b.toString(16).padStart(2, '0')).join('');\n}\n\n// ---- письма: тихие часы, ссылка «отписаться», журнал отправок ----\nfunction localHour(config, now) {\n  return new Date(now + config.timezone_offset_hours * 3600000).getUTCHours();\n}\n\nfunction quietNow(config, now) {\n  const [from, to] = config.quiet_hours || [];\n  if (from === undefined || from === to) return false;\n  const h = localHour(config, now);\n  return from > to ? h >= from || h < to : h >= from && h < to;\n}\n\nfunction unsubSig(config, email) {\n  return hmacSha256Hex(config.unsubscribe_secret, String(email).trim().toLowerCase()).slice(0, 32);\n}\n\nfunction unsubLink(config, email) {\n  return `${String(config.public_n8n_url).replace(/\\/$/, '')}/webhook/store-unsubscribe?e=${encodeURIComponent(email)}&s=${unsubSig(config, email)}`;\n}\n\n/** Messages: time | kind | ref | email | step | status | subject | detail */\nfunction messageLog(values) {\n  return sheetRows(values).map((r) => ({ ...r, step: Number(r.step || 0), t: Date.parse(r.time) || 0 }));\n}\n\nfunction suppressed(values) {\n  return new Set(sheetRows(values).map((r) => String(r.email || '').toLowerCase()).filter(Boolean));\n}\n\nconst { config } = $('Config').first().json;\nconst plans = $('Plan Carts').all().map((i) => i.json);\nconst ai = $('Cart Copy').isExecuted ? $input.all().map((i) => i.json) : [];\nconst forbidden = (config.forbidden || []).map((p) => new RegExp(p, 'iu'));\n\nfunction checkLine(text, plan) {\n  const line = String(text || '').trim().replace(/^[\"«]|[\"»]$/g, '');\n  if (!line) return [null, 'empty'];\n  if (line.length > 280) return [null, 'too_long'];\n  if (/https?:|www\\.|@/.test(line)) return [null, 'link'];\n  if (/\\d/.test(line)) return [null, 'numbers'];              // цены, проценты, сроки — только из шаблона\n  if (/(скидк|промокод|купон|бесплатн|discount|coupon|free)/i.test(line)) return [null, 'discount'];\n  if (/[{}<>]/.test(line)) return [null, 'markup'];\n  if (forbidden.some((r) => r.test(line))) return [null, 'forbidden'];\n  return [line, ''];\n}\n\nconst out = plans.map((p, i) => {\n  const name = p.name ? `${p.name}, з` : 'З';\n  const fallback = p.step === 1\n    ? 'вы выбрали товары, но не завершили заказ. Мы сохранили корзину — можно вернуться к ней в один клик.'\n    : 'напоминаем о корзине: товары пока ждут вас, но наличие не резервируется.';\n  const [line, rejected] = ai.length ? checkLine(ai[i]?.text, p) : [null, 'ai_off'];\n  const opening = line || fallback;\n  const subject = p.step === 1 ? `Вы оставили товары в корзине — ${config.store_name}` : `Ваша корзина в ${config.store_name} всё ещё ждёт`;\n  const lines = [\n    `${name}дравствуйте!`, '', line ? opening : opening.charAt(0).toUpperCase() + opening.slice(1), '',\n    'В корзине:', ...p.items.map((t) => `• ${t}`), '',\n    p.total ? `Сумма: ${p.total} ${p.currency}`.trim() : '',\n    `Вернуться к заказу: ${p.url}`,\n    p.discount_code ? `\\nПромокод на этот заказ: ${p.discount_code}` : '',\n    '', `Вопросы — просто ответьте на это письмо.`, config.store_name, '', '—',\n    `Не хотите получать такие письма: ${unsubLink(config, p.email)}`,\n  ];\n  return { json: { ...p, subject, text: lines.join('\\n').replace(/\\n{3,}/g, '\\n\\n'), ai_used: Boolean(line), ai_rejected: line ? '' : rejected } };\n});\nreturn out;\n"
      }
