      "parameters": {
        "jsCode": "// ================= НАСТРОЙКИ АГЕНТА =================\n// Меняйте только значения справа от двоеточия. Подробно — docs/02-setup.md.\nconst config = {\n  // Чья это база — агент отвечает от имени команды\n  company: 'Название компании',\n  audience: 'сотрудники компании', // кто задаёт вопросы: сотрудники, клиенты, партнёры\n  owner_contact: 'Отдел знаний, @username', // к кому идти, если ответа нет\n\n  // Источники: папка Google Drive и лист Sources (ссылки на страницы)\n  drive_folder_id: 'ВСТАВЬТЕ_ID_ПАПКИ',\n  spreadsheet_id: 'ВСТАВЬТЕ_ID_ТАБЛИЦЫ',\n\n  // Имя индекса в Simple Vector Store. Меняйте, если в одном n8n несколько баз.\n  index_key: 'kb_main',\n\n  // Нарезка документов\n  chunk_size: 1200,    // символов в одном фрагменте\n  chunk_overlap: 200,  // перекрытие соседних фрагментов\n  max_doc_chars: 300000, // длиннее — документ обрезается при индексации\n\n  // Поиск\n  search_top_k: 8,     // сколько фрагментов достаёт поиск\n  max_passages: 5,     // сколько фрагментов уходит модели\n  min_score: 0.35,     // ниже — «в документах нет» (0–1, см. docs/04-search.md)\n\n  // Telegram-чат команды: передачи человеку, пробелы в базе, отчёты переиндексации\n  team_chat_id: 'ВСТАВЬТЕ_ID_ЧАТА',\n\n  // Кто может спрашивать в Telegram: числовые ID пользователей. Пусто — никто.\n  // Бот отвечает незнакомцу его ID — так его проще добавить.\n  allowed_telegram_ids: [],\n\n  // Ключ, без которого вебхуки не отвечают. Длинная случайная строка.\n  agent_token: 'ЗАМЕНИТЕ_НА_ДЛИННУЮ_СЛУЧАЙНУЮ_СТРОКУ',\n\n  // Ограничения\n  max_message_chars: 2000,\n  rate_limit_messages: 30,\n  rate_limit_minutes: 10,\n  daily_agent_runs: 2000,\n  handoff_pause_minutes: 30,\n\n  // Служебная метка в системной инструкции. Если она появится в ответе — ответ не уйдёт.\n  canary: 'KB-57-CANARY',\n\n  // Ключ для прогона evals: запрос с заголовком x-agent-debug, равным ему, получает в ответе\n  // список вызванных инструментов. Пусто — режим выключен. Не кладите его на сайт.\n  debug_token: '',\n};\n\nreturn [{ json: { config, input: $input.first().json } }];\n"
