    {
      "id": "502bfe38-c11a-5f81-a0a6-8542c6db123f",
      "name": "Plan Sources",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        1580,
        1660
      ],
      "parameters": {
        "jsCode": "// Plan Sources: список документов для индекса — файлы папки Drive и ссылки из листа Sources.\n// ---- shared text helpers (inlined into Code nodes by the builder) ----\nconst STOP = new Set(('и в во не что он на я с со как а то все она так его но да ты к у же вы за бы по только ее мне было вот от меня еще нет о из ему теперь когда даже ну вдруг ли если уже или ни быть был него до вас нибудь опять уж вам ведь там потом себя ничего ей может они тут где есть надо ней для мы тебя их чем была сам чтоб без будто чего раз тоже себе под будет ж тогда кто этот того потому этого какой совсем ним здесь этом один почти мой тем чтобы нее сейчас были куда зачем всех никогда можно при наконец два об другой хоть после над больше тот через эти нас про всего них какая много разве три эту моя впрочем хорошо свою этой перед иногда лучше чуть том нельзя такой им более всегда конечно всю между это мой мою мое здравствуйте добрый день привет пожалуйста подскажите скажите хочу хотел хотела можно ли вы ваш ваша ваши the a an and or of to in on for is are be it this that with as at by from i you we my our your me do does how what can could please hi hello').split(' '));\n\nfunction stem(word) {\n  let w = word.toLowerCase().replace(/ё/g, 'е');\n  if (/^[a-z]+$/.test(w)) return w.replace(/(ing|ed|es|s)$/, '').slice(0, 7);\n  w = w.replace(/(ями|ами|иями|ией|ией|ого|ему|ому|ыми|ими|его|ая|яя|ое|ее|ие|ые|ой|ей|ий|ый|ов|ев|ам|ям|ах|ях|ом|ем|ую|юю|ть|ти|ешь|ет|ем|ете|ют|ут|ит|им|ите|ат|ят|ла|ло|ли|ся|сь|а|я|о|е|и|ы|у|ю|ь|й)$/, '');\n  return w.slice(0, 6);\n}\n\nfunction terms(text) {\n  return (String(text).toLowerCase().match(/[\\p{L}\\p{N}]+/gu) || [])\n    .filter((w) => w.length > 1 && !STOP.has(w))\n    .map(stem)\n    .filter((w) => w.length > 1);\n}\n\nfunction escapeHtml(text) {\n  return String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n}\n\nfunction sheetRows(values) {\n  const [head = [], ...rows] = values || [];\n  const keys = head.map((h) => String(h).trim().toLowerCase());\n  return rows.map((r, i) => Object.fromEntries([['_row', i + 2], ...keys.map((k, j) => [k, String(r[j] ?? '').trim()])]));\n}\n\nconst { config } = $('Config').first().json;\nconst drive = $('List Drive Files').first().json;\nconst sourcesSheet = $('Read Sources').first().json;\n\nconst TYPES = {\n  'application/vnd.google-apps.document': 'gdoc',\n  'application/pdf': 'pdf',\n  'text/plain': 'text',\n  'text/markdown': 'text',\n  'text/x-markdown': 'text',\n  'text/html': 'html',\n};\n\nif (drive.error) {\n  return [{ json: { abort: true, reason: `Не удалось прочитать папку Google Drive: ${String(drive.error.message || drive.error).slice(0, 300)}` } }];\n}\n\nconst plan = [];\nconst skipped = [];\nfor (const f of drive.files || []) {\n  const fetch = TYPES[f.mimeType] || (/\\.(md|txt)$/i.test(f.name) ? 'text' : null);\n  if (!fetch) {\n    skipped.push({ title: f.name, reason: `формат ${f.mimeType} не поддерживается` });\n    continue;\n  }\n  plan.push({\n    tool: 'extract_document',\n    source_kind: 'drive',\n    source_id: 'drive:' + f.id,\n    drive_id: f.id,\n    title: f.name.replace(/\\.(pdf|md|txt)$/i, ''),\n    url: f.webViewLink || `https://drive.google.com/file/d/${f.id}/view`,\n    mime: f.mimeType,\n    modified: f.modifiedTime || '',\n    fetch,\n  });\n}\n\nconst yes = (v) => !/^(нет|no|false|0|off|выкл)$/i.test(String(v || '').trim());\nconst sourceRows = sourcesSheet.error ? [] : sheetRows(sourcesSheet.values).filter((r) => r.url);\nfor (const r of sourceRows) {\n  if (!yes(r.enabled)) continue;\n  if (!/^https?:\\/\\//i.test(r.url)) {\n    skipped.push({ title: r.url, reason: 'ссылка должна начинаться с http:// или https://' });\n    continue;\n  }\n  plan.push({\n    tool: 'extract_document',\n    source_kind: 'url',\n    source_id: 'url:' + r.url,\n    drive_id: '',\n    title: r.title || r.url.replace(/^https?:\\/\\//, ''),\n    url: r.url,\n    mime: 'text/html',\n    modified: '',\n    fetch: 'url',\n  });\n}\n\nplan.sort((a, b) => a.title.localeCompare(b.title, 'ru'));\nconst warnings = sourcesSheet.error ? ['Лист Sources не прочитан — ссылки не проиндексированы'] : [];\nif (!plan.length) {\n  // Пустой индекс — тоже результат: старые фрагменты удалятся.\n  return [{ json: { empty: true, skipped, warnings } }];\n}\nreturn plan.map((p, i) => ({ json: { ...p, plan_index: i, skipped: i === 0 ? skipped : [], warnings: i === 0 ? warnings : [] } }));\n"
      }
    },
