      "parameters": {
        "jsCode": "// Score: баллы по рубрике. Факты из формы считает код, суждения берутся из принятой оценки модели.\n// ---- shared text helpers (inlined into Code nodes by the builder) ----\nconst STOP = new Set(('и в во не что он на я с со как а то все она так его но да ты к у же вы за бы по только ее мне было вот от меня еще нет о из ему теперь когда даже ну вдруг ли если уже или ни быть был него до вас нибудь опять уж вам ведь там потом себя ничего ей может они тут где есть надо ней для мы тебя их чем была сам чтоб без будто чего раз тоже себе под будет ж тогда кто этот того потому этого какой совсем ним здесь этом один почти мой тем чтобы нее сейчас были куда зачем всех никогда можно при наконец два об другой хоть после над больше тот через эти нас про всего них какая много разве три эту моя впрочем хорошо свою этой перед иногда лучше чуть том нельзя такой им более всегда конечно всю между это мой мою мое здравствуйте добрый день привет пожалуйста подскажите скажите хочу хотел хотела можно ли вы ваш ваша ваши the a an and or of to in on for is are be it this that with as at by from i you we my our your me do does how what can could please hi hello').split(' '));\n\nfunction stem(word) {\n  let w = word.toLowerCase().replace(/ё/g, 'е');\n  if (/^[a-z]+$/.test(w)) return w.replace(/(ing|ed|es|s)$/, '').slice(0, 7);\n  w = w.replace(/(ями|ами|иями|ией|ией|ого|ему|ому|ыми|ими|его|ая|яя|ое|ее|ие|ые|ой|ей|ий|ый|ов|ев|ам|ям|ах|ях|ом|ем|ую|юю|ть|ти|ешь|ет|ем|ете|ют|ут|ит|им|ите|ат|ят|ла|ло|ли|ся|сь|а|я|о|е|и|ы|у|ю|ь|й)$/, '');\n  return w.slice(0, 6);\n}\n\nfunction terms(text) {\n  return (String(text).toLowerCase().match(/[\\p{L}\\p{N}]+/gu) || [])\n    .filter((w) => w.length > 1 && !STOP.has(w))\n    .map(stem)\n    .filter((w) => w.length > 1);\n}\n\nfunction escapeHtml(text) {\n  return String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n}\n\nfunction sheetRows(values) {\n  const [head = [], ...rows] = values || [];\n  const keys = head.map((h) => String(h).trim().toLowerCase());\n  return rows.map((r, i) => Object.fromEntries([['_row', i + 2], ...keys.map((k, j) => [k, String(r[j] ?? '').trim()])]));\n}\n\nconst { config } = $('Config').first().json;\nconst d = $('Dedupe').first().json;\nconst lead = d.lead;\nconst result = $input.first().json || {};\nconst steps = Array.isArray(result.intermediateSteps) ? result.intermediateSteps : [];\nconst parse = (o) => { try { o = typeof o === 'string' ? JSON.parse(o) : o; } catch { return null; } return Array.isArray(o) ? (o[0]?.json ?? o[0]) : o; };\nconst accepted = [...steps].reverse().find((s) => s.action?.tool === 'submit_assessment' && parse(s.observation)?.ok === true);\nconst a = accepted ? accepted.action.toolInput : null;\nconst pages = steps.filter((s) => s.action?.tool === 'fetch_page' && parse(s.observation)?.ok === true).map((s) => s.action.toolInput.url);\n\nfunction amount(text) {\n  const t = String(text || '').toLowerCase();\n  const m = /(\\d+(?:[ .,]\\d{3})*(?:[.,]\\d+)?)\\s*(k|к|тыс|тысяч|thousand|m|млн|million)?/.exec(t);\n  if (!m) return null;\n  let n = Number(m[1].replace(/[ ,](?=\\d{3}\\b)/g, '').replace(',', '.').replace(/\\.(?=\\d{3}\\b)/g, ''));\n  if (/^(k|к|тыс|тысяч|thousand)$/.test(m[2] || '')) n *= 1000;\n  if (/^(m|млн|million)$/.test(m[2] || '')) n *= 1000000;\n  return isFinite(n) ? n : null;\n}\nconst budget = amount(lead.budget);\nconst total = config.rubric.reduce((s, r) => s + r.weight, 0) || 1;\nlet points = 0;\nconst reasons = [];\nfor (const r of config.rubric) {\n  let share = 0;\n  let why = '';\n  if (r.type === 'model') {\n    const v = a ? String(a[r.field] || '').toLowerCase() : '';\n    share = a ? (r.points[v] ?? 0) : 0;\n    why = a ? v : 'нет оценки модели';\n  } else if (r.type === 'budget') {\n    share = budget === null ? 0 : budget >= r.min ? 1 : 0.4;\n    why = budget === null ? 'не указан' : String(budget);\n  } else if (r.type === 'corporate_email') {\n    share = lead.corporate_email ? 1 : 0;\n    why = lead.corporate_email ? lead.email.split('@')[1] : 'нет';\n  } else if (r.type === 'present') {\n    share = lead[r.field] ? 1 : 0;\n    why = lead[r.field] ? 'есть' : 'нет';\n  }\n  const got = Math.round(r.weight * share * 100 / total);\n  points += r.weight * share;\n  reasons.push(`${got > 0 ? '+' : '±'}${got} ${r.label}: ${why}`);\n}\nconst score = Math.round((points * 100) / total);\nconst flags = a ? String(a.red_flags || '').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean) : [];\nconst disq = flags.filter((f) => (config.disqualify_flags || []).includes(f));\nlet tier = score >= config.hot_score ? 'hot' : score >= config.warm_score ? 'warm' : 'cold';\nif (disq.length) tier = 'disqualified';\nconst review = [];\nif (!a) review.push('оценка модели не получена — проверьте лида вручную');\nif (d.crm_error) review.push('CRM не прочиталась: проверка на дубли не выполнена');\n\nconst size = a ? a.company_size : 'unknown';\nconst segment = (config.enterprise_sizes || []).includes(size) || (budget !== null && budget >= config.enterprise_budget) ? 'enterprise' : 'smb';\nconst questions = a ? String(a.questions || '').split(/\\n|;|\\?\\s/).map((q) => q.trim()).filter(Boolean).slice(0, 3).map((q) => (q.endsWith('?') ? q : q + '?')) : [];\nreturn [{ json: {\n  lead, debug: d.debug, duplicate: d.duplicate, score, tier, segment, reasons, flags, disqualified: disq, review,\n  assessment: a ? { fit: a.fit, intent: a.intent, company_size: a.company_size, urgency: a.urgency, summary: String(a.summary || '').slice(0, 600), questions } : null,\n  pages,\n} }];\n"
      }
    },
    {
      "id": "e6ba8af5-d119-5c5a-866d-11c7946466c7",
      "name": "Route",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        1860,
        0
      ],
      "parameters": {
        "jsCode": "// Route: менеджер, строка в CRM, сообщение менеджеру и решение о письме лиду.\n// ---- shared text helpers (inlined into Code nodes by the builder) ----\nconst STOP = new Set(('и в во не что он на я с со как а то все она так его но да ты к у же вы за бы по только ее мне было вот от меня еще нет о из ему теперь когда даже ну вдруг ли если уже или ни быть был него до вас нибудь опять уж вам ведь там потом себя ничего ей может они тут где есть надо ней для мы тебя их чем была сам чтоб без будто чего раз тоже себе под будет ж тогда кто этот того потому этого какой совсем ним здесь этом один почти мой тем чтобы нее сейчас были куда зачем всех никогда можно при наконец два об другой хоть после над больше тот через эти нас про всего них какая много разве три эту моя впрочем хорошо свою этой перед иногда лучше чуть том нельзя такой им более всегда конечно всю между это мой мою мое здравствуйте добрый день привет пожалуйста подскажите скажите хочу хотел хотела можно ли вы ваш ваша ваши the a an and or of to in on for is are be it this that with as at by from i you we my our your me do does how what can could please hi hello').split(' '));\n\nfunction stem(word) {\n  let w = word.toLowerCase().replace(/ё/g, 'е');\n  if (/^[a-z]+$/.test(w)) return w.replace(/(ing|ed|es|s)$/, '').slice(0, 7);\n  w = w.replace(/(ями|ами|иями|ией|ией|ого|ему|ому|ыми|ими|его|ая|яя|ое|ее|ие|ые|ой|ей|ий|ый|ов|ев|ам|ям|ах|ях|ом|ем|ую|юю|ть|ти|ешь|ет|ем|ете|ют|ут|ит|им|ите|ат|ят|ла|ло|ли|ся|сь|а|я|о|е|и|ы|у|ю|ь|й)$/, '');\n  return w.slice(0, 6);\n}\n\nfunction terms(text) {\n  return (String(text).toLowerCase().match(/[\\p{L}\\p{N}]+/gu) || [])\n    .filter((w) => w.length > 1 && !STOP.has(w))\n    .map(stem)\n    .filter((w) => w.length > 1);\n}\n\nfunction escapeHtml(text) {\n  return String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n}\n\nfunction sheetRows(values) {\n  const [head = [], ...rows] = values || [];\n  const keys = head.map((h) => String(h).trim().toLowerCase());\n  return rows.map((r, i) => Object.fromEntries([['_row', i + 2], ...keys.map((k, j) => [k, String(r[j] ?? '').trim()])]));\n}\n\n// Колонки листа Leads, по порядку (A…V)\nconst COLS = ['lead_id', 'received', 'name', 'email', 'phone', 'company', 'domain', 'website', 'source', 'message', 'budget',\n  'score', 'tier', 'segment', 'owner', 'status', 'reasons', 'summary', 'questions', 'flags', 'repeat_count', 'last_seen'];\n\nconst { config } = $('Config').first().json;\nconst s = $input.first().json;\nconst lead = s.lead;\nconst store = $getWorkflowStaticData('global');\nstore.rr = store.rr || {};\nconst now = new Date().toISOString();\nconst active = (config.owners || []).filter((o) => o.active);\n\nlet owner = null;\nlet routing = '';\nif (s.duplicate && active.find((o) => o.id === s.duplicate.owner)) {\n  owner = active.find((o) => o.id === s.duplicate.owner);\n  routing = 'повторная заявка — тому же менеджеру';\n} else if (s.tier !== 'disqualified') {\n  const pool = active.filter((o) => (o.segments || []).includes(s.segment));\n  if (pool.length) {\n    const i = (store.rr[s.segment] || 0) % pool.length;\n    owner = pool[i];\n    store.rr[s.segment] = i + 1;\n    routing = `по кругу в сегменте ${s.segment}`;\n  } else {\n    routing = `в сегменте ${s.segment} нет активных менеджеров`;\n  }\n} else {\n  routing = 'дисквалифицирован: ' + s.disqualified.join(', ');\n}\n\nconst row = {\n  lead_id: lead.lead_id, received: lead.received, name: lead.name, email: lead.email, phone: lead.phone, company: lead.company,\n  domain: lead.domain, website: lead.website, source: lead.source, message: lead.message, budget: lead.budget,\n  score: String(s.score), tier: s.tier, segment: s.segment, owner: owner ? owner.id : '', status: s.tier === 'disqualified' ? 'disqualified' : 'new',\n  reasons: s.reasons.join('; '), summary: s.assessment?.summary || '', questions: (s.assessment?.questions || []).join(' '),\n  flags: [...s.flags, ...s.review].join(', '), repeat_count: '0', last_seen: now,\n};\nlet http;\nif (s.duplicate) {\n  const d = s.duplicate;\n  const merged = { ...d };\n  for (const k of COLS) if (row[k] && !['lead_id', 'received', 'repeat_count', 'status'].includes(k)) merged[k] = row[k];\n  merged.message = [d.message, `${now.slice(0, 10)}: ${lead.message}`].filter(Boolean).join('\\n---\\n').slice(0, 5000);\n  merged.repeat_count = String(Number(d.repeat_count || 0) + 1);\n  merged.owner = owner ? owner.id : d.owner;\n  http = { method: 'PUT', path: `${encodeURIComponent(`Leads!A${d._row}`)}?valueInputOption=RAW`, body: { values: [COLS.map((k) => merged[k] ?? '')] } };\n} else {\n  http = { method: 'POST', path: `${encodeURIComponent('Leads!A1')}:append?valueInputOption=RAW&insertDataOption=INSERT_ROWS`, body: { values: [COLS.map((k) => row[k] ?? '')] } };\n}\n\nconst icon = { hot: '🔥', warm: '🟡', cold: '⚪️', disqualified: '⛔️' }[s.tier];\nconst card = [\n  `<b>${icon} ${escapeHtml(lead.name || 'Без имени')}${lead.company ? ' · ' + escapeHtml(lead.company) : ''} — ${s.score}/100</b>`,\n  s.duplicate ? `↩️ Повторная заявка (${Number(s.duplicate.repeat_count || 0) + 1}-я), первая — ${escapeHtml(s.duplicate.received.slice(0, 10))}` : '',\n  [lead.email, lead.phone].filter(Boolean).map(escapeHtml).join(' · '),\n  lead.website ? escapeHtml(lead.website) : '',\n  '',\n  s.assessment ? `<b>Суть:</b> ${escapeHtml(s.assessment.summary)}` : '',\n  `<blockquote>${escapeHtml(lead.message.slice(0, 700) || '—')}</blockquote>`,\n  `<b>Баллы:</b>\\n${s.reasons.map(escapeHtml).join('\\n')}`,\n  s.assessment?.questions?.length ? `<b>Спросить на звонке:</b>\\n${s.assessment.questions.map((q) => '• ' + escapeHtml(q)).join('\\n')}` : '',\n  s.flags.length || s.review.length ? `<b>Флаги:</b> ${escapeHtml([...s.flags, ...s.review].join(', '))}` : '',\n  `<i>${escapeHtml(lead.lead_id)} · ${escapeHtml(lead.source)} · ${escapeHtml(routing)}</i>`,\n].filter(Boolean).join('\\n');\n\nconst notify = [];\nif (owner) notify.push({ chat_id: owner.chat_id, text: card });\nif (config.team_chat_id && (s.tier === 'hot' || !owner && s.tier !== 'disqualified' || s.review.length)) notify.push({ chat_id: config.team_chat_id, text: card });\n\nconst clarify = Boolean(config.clarify_by_email && lead.email && !s.duplicate && (config.clarify_tiers || []).includes(s.tier) && s.assessment?.questions?.length);\nconst email = clarify ? {\n  to: lead.email,\n  subject: `${config.company}: пара вопросов по вашей заявке`,\n  text: [`Здравствуйте${lead.name ? ', ' + lead.name : ''}!`, '', `Спасибо за заявку в ${config.company}. Чтобы предложить подходящее решение, ответьте, пожалуйста, на несколько вопросов:`, '',\n    ...s.assessment.questions.map((q, i) => `${i + 1}. ${q}`), '', 'Можно ответить прямо на это письмо.', '', config.clarify_from_name].join('\\n'),\n} : null;\n\nconst response = { ok: true, lead_id: lead.lead_id };\nconst report = { ...response, score: s.score, tier: s.tier, segment: s.segment, owner: owner ? owner.id : '', duplicate: Boolean(s.duplicate),\n  reasons: s.reasons, flags: s.flags, review: s.review, assessment: s.assessment, pages: s.pages, email_sent: clarify, routing };\nreturn [{ json: { http, notify, email, debug: s.debug, response: s.debug ? report : response } }];\n"
      }
