      "parameters": {
        "jsCode": "// ================= НАСТРОЙКИ КОМАНДЫ АГЕНТОВ =================\n// Меняйте только значения справа от двоеточия. Подробно — docs/02-setup.md.\nconst config = {\n  // О компании — агенты говорят от её имени\n  company: 'Название компании',\n  about: 'Чем вы занимаетесь, одним предложением',\n  services: 'Что вы продаёте и для кого, 1–3 предложения: агент по лидам опирается на это',\n  support_hours: 'пн–пт 9:00–18:00 (Киев)',\n  contact_fallback: 'hello@example.com',\n  timezone: 'Europe/Kyiv',\n\n  // Google Таблица с листами Knowledge, Leads, Tickets, Inbox, Log\n  spreadsheet_id: 'ВСТАВЬТЕ_ID_ТАБЛИЦЫ',\n\n  // Telegram-чат команды: передачи, горячие лиды, срочные письма, ежедневный отчёт\n  team_chat_id: 'ВСТАВЬТЕ_ID_ЧАТА',\n\n  // Ключи вебхука. agent_token — для сайта и систем, team_token — для запросов команды\n  // (только они могут вызвать агента отчётов). Длинные случайные строки, разные.\n  agent_token: 'ЗАМЕНИТЕ_НА_ДЛИННУЮ_СЛУЧАЙНУЮ_СТРОКУ',\n  team_token: 'ЗАМЕНИТЕ_НА_ДРУГУЮ_СЛУЧАЙНУЮ_СТРОКУ',\n\n  // Почта: свои адреса (письма с них не разбираются) и что слать команде\n  own_emails: ['hello@example.com'],\n  email_notify: 'urgent', // 'urgent' — только срочные письма; 'all' — сводку по каждому письму\n\n  // Лиды: с какого балла (0–100) лид считается горячим и команда получает сигнал\n  hot_lead_score: 70,\n  min_budget_eur: 1000, // бюджет от этой суммы даёт лиду полный балл за бюджет\n\n  // Ограничения\n  max_message_chars: 4000,\n  rate_limit_messages: 20,     // сообщений от одного клиента...\n  rate_limit_minutes: 10,      // ...за столько минут\n  daily_agent_runs: 1000,      // потолок обращений к оркестратору в сутки\n  // Дневной лимит вызовов каждого агента. Исчерпан — оркестратор не может его вызвать.\n  agent_budgets: {\n    email_triage_agent: 300,\n    leads_agent: 300,\n    support_agent: 500,\n    reports_agent: 20,\n  },\n  handoff_pause_minutes: 30,\n  kb_min_score: 0.3,\n\n  // Обещания, которые агенты давать не могут: регулярные выражения\n  forbidden: [\n    '(верн(ём|ем|у)|возврат(им)?|компенсиру(ем|ю)|дадим|предостав(им|лю)|сделаем)[^.!?]{0,40}(деньг|скидк|компенсац|бесплатн|промокод)',\n    'гарантиру(ю|ем)',\n    '(refund|compensate|give you a discount|guarantee)',\n  ],\n\n  // Служебная метка в инструкциях. Если она появится в ответе — ответ не уйдёт.\n  canary: 'OPS-73-CANARY',\n\n  // Ключ для evals: запрос с заголовком x-agent-debug, равным ему, получает в ответе\n  // трассу — каких агентов вызвал оркестратор. Пусто — выключено. Не кладите на сайт.\n  debug_token: '',\n};\n\nreturn [{ json: { config, input: $input.first().json } }];\n"
