      "parameters": {
        "jsCode": "// Rank Articles: ищет в листе Knowledge статьи под запрос модели.\n// Колонки: id | question | answer | tags | updated. Поиск по словам с учётом окончаний,\n// без векторной базы: для FAQ до нескольких сотен статей этого достаточно.\n// ---- shared text helpers (inlined into Code nodes by the builder) ----\nconst STOP = new Set(('и в во не что он на я с со как а то все она так его но да ты к у же вы за бы по только ее мне было вот от меня еще нет о из ему теперь когда даже ну вдруг ли если уже или ни быть был него до вас нибудь опять уж вам ведь там потом себя ничего ей может они тут где есть надо ней для мы тебя их чем была сам чтоб без будто чего раз тоже себе под будет ж тогда кто этот того потому этого какой совсем ним здесь этом один почти мой тем чтобы нее сейчас были куда зачем всех никогда можно при наконец два об другой хоть после над больше тот через эти нас про всего них какая много разве три эту моя впрочем хорошо свою этой перед иногда лучше чуть том нельзя такой им более всегда конечно всю между это мой мою мое здравствуйте добрый день привет пожалуйста подскажите скажите хочу хотел хотела можно ли вы ваш ваша ваши the a an and or of to in on for is are be it this that with as at by from i you we my our your me do does how what can could please hi hello').split(' '));\n\nfunction stem(word) {\n  let w = word.toLowerCase().replace(/ё/g, 'е');\n  if (/^[a-z]+$/.test(w)) return w.replace(/(ing|ed|es|s)$/, '').slice(0, 7);\n  w = w.replace(/(ями|ами|иями|ией|ией|ого|ему|ому|ыми|ими|его|ая|яя|ое|ее|ие|ые|ой|ей|ий|ый|ов|ев|ам|ям|ах|ях|ом|ем|ую|юю|ть|ти|ешь|ет|ем|ете|ют|ут|ит|им|ите|ат|ят|ла|ло|ли|ся|сь|а|я|о|е|и|ы|у|ю|ь|й)$/, '');\n  return w.slice(0, 6);\n}\n\nfunction terms(text) {\n  return (String(text).toLowerCase().match(/[\\p{L}\\p{N}]+/gu) || [])\n    .filter((w) => w.length > 1 && !STOP.has(w))\n    .map(stem)\n    .filter((w) => w.length > 1);\n}\n\nfunction escapeHtml(text) {\n  return String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n}\n\nfunction sheetRows(values) {\n  const [head = [], ...rows] = values || [];\n  const keys = head.map((h) => String(h).trim().toLowerCase());\n  return rows.map((r, i) => Object.fromEntries([['_row', i + 2], ...keys.map((k, j) => [k, String(r[j] ?? '').trim()])]));\n}\n\nconst { config, input } = $('Config').first().json;\nconst failed = $input.first().json.error;\nif (failed) {\n  return [{ json: { found: false, service_error: String(failed.message || failed).slice(0, 300), note: 'Сейчас база недоступна. Извинись и предложи передать вопрос менеджеру (handoff_to_human). Не отвечай по памяти.' } }];\n}\nconst rows = sheetRows($input.first().json.values).filter((r) => r.answer);\nconst query = terms(input.query || '');\n\nif (!rows.length) {\n  return [{ json: { found: false, articles: [], note: 'База знаний пуста или лист Knowledge не найден. Не отвечай по памяти: предложи создать обращение (create_ticket) или передать менеджеру.' } }];\n}\nif (!query.length) {\n  return [{ json: { found: false, articles: [], note: 'Пустой запрос. Переформулируй вопрос клиента ключевыми словами и вызови поиск ещё раз.' } }];\n}\n\nconst docs = rows.map((r) => ({ r, head: terms(`${r.question} ${r.tags}`), body: terms(r.answer) }));\nconst df = {};\nfor (const d of docs) for (const t of new Set([...d.head, ...d.body])) df[t] = (df[t] || 0) + 1;\nconst idf = (t) => Math.log(1 + docs.length / (df[t] || 0.5));\nconst unique = [...new Set(query)];\nconst total = unique.reduce((a, t) => a + idf(t), 0);\n\nconst scored = docs.map((d) => {\n  const head = new Set(d.head);\n  const body = new Set(d.body);\n  let hit = 0;\n  for (const t of unique) {\n    if (head.has(t)) hit += idf(t);\n    else if (body.has(t)) hit += idf(t) * 0.6;\n  }\n  return { id: d.r.id || `row-${d.r._row}`, question: d.r.question, answer: d.r.answer, updated: d.r.updated, score: Math.round((hit / total) * 100) / 100 };\n}).filter((a) => a.score > 0).sort((a, b) => b.score - a.score).slice(0, 3);\n\nconst found = scored.length > 0 && scored[0].score >= config.kb_min_score;\nreturn [{ json: {\n  found,\n  articles: found ? scored : [],\n  note: found\n    ? 'Отвечай только по этим статьям. Если они не отвечают на вопрос полностью — скажи, чего не хватает, и предложи передать менеджеру.'\n    : 'В базе знаний нет ответа на этот вопрос. Не придумывай ответ: предложи создать обращение (create_ticket) или передать менеджеру.',\n} }];\n"
      }
