        "jsCode": "// ================= НАСТРОЙКИ АГЕНТСТВА =================\n// Меняйте только значения справа от двоеточия. Подробно — docs/02-setup.md.\nconst config = {\n  // Агентство\n  company: 'Название агентства',\n  about: 'Покупка, продажа и аренда квартир в Киеве',\n  city: 'Киев',\n  support_hours: 'пн–сб 9:00–19:00',\n  contact_fallback: '+380 00 000 00 00',\n  timezone: 'Europe/Kyiv',\n  currency: 'USD',\n  phone_country: '380',        // код страны для номеров, которые клиент пишет с 0            // валюта цен в листе Listings и бюджетов по умолчанию\n  mortgage_partner: 'ипотечный брокер-партнёр агентства', // кому передаём вопросы по ипотеке\n\n  // Google Таблица с листами Listings, Leads, Viewings, Log\n  spreadsheet_id: 'ВСТАВЬТЕ_ID_ТАБЛИЦЫ',\n\n  // Telegram-чат агентства: новые лиды, передачи, сводка follow-up\n  team_chat_id: 'ВСТАВЬТЕ_ID_ЧАТА',\n\n  // Риелторы. id — как в колонке agent_id листа Listings.\n  // calendar_id — Google Календарь риелтора (его email или ID календаря).\n  // chat_id — личный Telegram риелтора для записей на просмотр; пусто — в чат агентства.\n  // areas и deal_types — по ним лид без объекта попадает к нужному риелтору.\n  agents: [\n    { id: 'maria', name: 'Мария', calendar_id: 'maria@example.com', chat_id: '', areas: ['Печерский', 'Голосеевский'], deal_types: ['buy'] },\n    { id: 'pavel', name: 'Павел', calendar_id: 'pavel@example.com', chat_id: '', areas: ['Оболонский', 'Подольский'], deal_types: ['buy', 'rent'] },\n    { id: 'dina', name: 'Дина', calendar_id: 'dina@example.com', chat_id: '', areas: [], deal_types: ['rent'] },\n  ],\n\n  // Просмотры\n  viewing_minutes: 60,          // длительность просмотра\n  buffer_minutes: 30,           // зазор до и после другого события риелтора\n  lead_time_minutes: 120,       // не раньше, чем через столько минут от сейчас\n  booking_window_days: 21,      // на сколько дней вперёд можно записаться\n  offer_slots: 3,               // сколько вариантов показывать\n  viewing_hours: {\n    mon: ['10:00', '19:00'], tue: ['10:00', '19:00'], wed: ['10:00', '19:00'],\n    thu: ['10:00', '19:00'], fri: ['10:00', '19:00'], sat: ['11:00', '16:00'], sun: null,\n  },\n\n  // Лиды\n  hot_score: 70,               // от этого балла лид горячий — сигнал риелтору сразу\n  follow_up_days: [1, 3, 7],   // через сколько дней тишины напоминать\n  follow_up_texts: [\n    'Здравствуйте! Подобрал для вас варианты — остались вопросы или посмотрим что-то вживую?',\n    'Добрый день! Появились новые объекты по вашим параметрам. Подобрать?',\n    'Здравствуйте! Если поиск ещё актуален — напишите, обновлю подборку. Если уже не нужно — тоже дайте знать.',\n  ],\n\n  // Ключи\n  agent_token: 'ЗАМЕНИТЕ_НА_ДЛИННУЮ_СЛУЧАЙНУЮ_СТРОКУ',\n  debug_token: '',\n\n  // Ограничения\n  max_message_chars: 2000,\n  rate_limit_messages: 20,\n  rate_limit_minutes: 10,\n  daily_agent_runs: 1000,\n  handoff_pause_minutes: 30,\n\n  // Обещания, которые агент давать не может\n  forbidden: [\n    '(верн(ём|ем|у)|компенсиру(ем|ю)|дадим|предостав(им|лю)|сделаем)[^.!?]{0,40}(деньг|скидк|компенсац|бесплатн)',\n    'гарантиру(ю|ем)',\n    '(одобр(ят|ит|им)|точно дадут)[^.!?]{0,30}(ипотек|кредит)',\n    '(ипотек|кредит)[^.!?]{0,30}(точно |обязательно )?(одобр(ят|ит|им)|дадут)',\n    '(владелец|собственник) (уступит|скинет|согласится)',\n    '(торг|скидк)[^.!?]{0,20}(точно|гарантир|обязательно)',\n  ],\n  canary: 'RE-48-CANARY',\n};\n\nreturn [{ json: { config, input: $input.first().json } }];\n"
