        "jsCode": "// Lead Upsert: обновляет карточку лида, считает балл и назначает риелтора.\n// ---- shared text helpers (inlined into Code nodes by the builder) ----\nconst STOP = new Set(('и в во не что он на я с со как а то все она так его но да ты к у же вы за бы по только ее мне было вот от меня еще нет о из ему теперь когда даже ну вдруг ли если уже или ни быть был него до вас нибудь опять уж вам ведь там потом себя ничего ей может они тут где есть надо ней для мы тебя их чем была сам чтоб без будто чего раз тоже себе под будет ж тогда кто этот того потому этого какой совсем ним здесь этом один почти мой тем чтобы нее сейчас были куда зачем всех никогда можно при наконец два об другой хоть после над больше тот через эти нас про всего них какая много разве три эту моя впрочем хорошо свою этой перед иногда лучше чуть том нельзя такой им более всегда конечно всю между это мой мою мое здравствуйте добрый день привет пожалуйста подскажите скажите хочу хотел хотела можно ли вы ваш ваша ваши the a an and or of to in on for is are be it this that with as at by from i you we my our your me do does how what can could please hi hello').split(' '));\n\nfunction stem(word) {\n  let w = word.toLowerCase().replace(/ё/g, 'е');\n  if (/^[a-z]+$/.test(w)) return w.replace(/(ing|ed|es|s)$/, '').slice(0, 7);\n  w = w.replace(/(ями|ами|иями|ией|ией|ого|ему|ому|ыми|ими|его|ая|яя|ое|ее|ие|ые|ой|ей|ий|ый|ов|ев|ам|ям|ах|ях|ом|ем|ую|юю|ть|ти|ешь|ет|ем|ете|ют|ут|ит|им|ите|ат|ят|ла|ло|ли|ся|сь|а|я|о|е|и|ы|у|ю|ь|й)$/, '');\n  return w.slice(0, 6);\n}\n\nfunction terms(text) {\n  return (String(text).toLowerCase().match(/[\\p{L}\\p{N}]+/gu) || [])\n    .filter((w) => w.length > 1 && !STOP.has(w))\n    .map(stem)\n    .filter((w) => w.length > 1);\n}\n\nfunction escapeHtml(text) {\n  return String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n}\n\nfunction sheetRows(values) {\n  const [head = [], ...rows] = values || [];\n  const keys = head.map((h) => String(h).trim().toLowerCase());\n  return rows.map((r, i) => Object.fromEntries([['_row', i + 2], ...keys.map((k, j) => [k, String(r[j] ?? '').trim()])]));\n}\n\n// ---- агентство: общие функции (встраиваются в узлы Code сборщиком) ----\nconst LEAD_COLS = ['created', 'lead_id', 'session_id', 'channel', 'source', 'name', 'phone', 'email', 'telegram', 'deal_type',\n  'property_type', 'area', 'rooms', 'budget_max', 'currency', 'timeline', 'mortgage', 'score', 'segment', 'agent_id', 'stage',\n  'listing_ids', 'viewing_id', 'last_contact', 'follow_ups', 'notified', 'notes'];\nconst colLetter = (index) => {\n  let s = '';\n  let n = index + 1;\n  while (n) {\n    const r = (n - 1) % 26;\n    s = String.fromCharCode(65 + r) + s;\n    n = Math.floor((n - 1) / 26);\n  }\n  return s;\n};\nconst LEAD_LAST = colLetter(LEAD_COLS.length - 1);\nconst leadRange = (row) => `Leads!A${row}:${LEAD_LAST}${row}`;\nconst leadValues = (lead) => LEAD_COLS.map((c) => String(lead[c] ?? ''));\n\nconst normId = (v) => String(v || '').toUpperCase().replace(/[^A-Z0-9-]/g, '');\nconst norm = (v) => String(v || '').toLowerCase().replace(/ё/g, 'е').trim();\nconst digits = (v) => String(v || '').replace(/\\D/g, '');\nconst num = (v) => {\n  const d = String(v ?? '').replace(/\\s/g, '').replace(',', '.').replace(/[^\\d.]/g, '');\n  return d ? Number(d) : 0;\n};\n\n// Ищем лида этого диалога, а если его нет — по телефону.\nfunction findLead(rows, session_id, phone) {\n  const bySession = rows.find((r) => r.session_id === session_id);\n  if (bySession) return bySession;\n  const p = digits(phone);\n  return p.length >= 9 ? rows.find((r) => digits(r.phone).endsWith(p.slice(-9))) : null;\n}\n\n// ---- время в часовом поясе агентства ----\nfunction tzParts(ms, tz) {\n  const parts = {};\n  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: tz, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit',\n    hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;\n  return { date: `${parts.year}-${parts.month}-${parts.day}`, time: `${parts.hour}:${parts.minute}`, weekday: parts.weekday.toLowerCase().slice(0, 3) };\n}\n// Местное время → момент в UTC (с учётом перехода на летнее время).\nfunction zonedToMs(date, time, tz) {\n  const [y, mo, d] = date.split('-').map(Number);\n  const [h, mi] = time.split(':').map(Number);\n  let guess = Date.UTC(y, mo - 1, d, h, mi);\n  for (let i = 0; i < 2; i++) {\n    const p = tzParts(guess, tz);\n    const [py, pmo, pd] = p.date.split('-').map(Number);\n    const [ph, pmi] = p.time.split(':').map(Number);\n    const shown = Date.UTC(py, pmo - 1, pd, ph, pmi);\n    guess += Date.UTC(y, mo - 1, d, h, mi) - shown;\n  }\n  return guess;\n}\nconst addDays = (date, n) => new Date(Date.parse(date + 'T12:00:00Z') + n * 86400000).toISOString().slice(0, 10);\nconst WEEK = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];\nconst weekdayOf = (date) => WEEK[new Date(date + 'T12:00:00Z').getUTCDay()];\nconst RU_DAYS = { mon: 'понедельник', tue: 'вторник', wed: 'среда', thu: 'четверг', fri: 'пятница', sat: 'суббота', sun: 'воскресенье' };\nfunction spoken(ms, tz) {\n  return new Intl.DateTimeFormat('ru-RU', { timeZone: tz, weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' }).format(new Date(ms));\n}\n\n// «сегодня», «завтра», «пятница», «2026-11-21», «+3» → дата; пусто — ближайшие дни.\nfunction resolveDate(word, today) {\n  const w = norm(word);\n  if (!w) return { from: today, days: 7 };\n  if (/^\\d{4}-\\d{2}-\\d{2}$/.test(w)) return { from: w, days: 1 };\n  if (['today', 'сегодня'].includes(w)) return { from: today, days: 1 };\n  if (['tomorrow', 'завтра'].includes(w)) return { from: addDays(today, 1), days: 1 };\n  if (['послезавтра'].includes(w)) return { from: addDays(today, 2), days: 1 };\n  const plus = /^\\+(\\d{1,2})$/.exec(w);\n  if (plus) return { from: addDays(today, Number(plus[1])), days: 1 };\n  const names = { mon: ['mon', 'monday', 'понедельник', 'пн'], tue: ['tue', 'tuesday', 'вторник', 'вт'], wed: ['wed', 'wednesday', 'среда', 'среду', 'ср'],\n    thu: ['thu', 'thursday', 'четверг', 'чт'], fri: ['fri', 'friday', 'пятница', 'пятницу', 'пт'], sat: ['sat', 'saturday', 'суббота', 'субботу', 'сб'],\n    sun: ['sun', 'sunday', 'воскресенье', 'вс'] };\n  const day = Object.keys(names).find((k) => names[k].includes(w));\n  if (day) {\n    for (let i = 0; i < 7; i++) if (weekdayOf(addDays(today, i)) === day) return { from: addDays(today, i), days: 1 };\n  }\n  if (['week', 'неделя', 'на неделе', 'this week'].includes(w)) return { from: today, days: 7 };\n  return null;\n}\n\n// Свободные окна риелтора: часы просмотров минус занятость с зазором.\nfunction freeSlots(config, busy, from, days, nowMs, limit) {\n  const tz = config.timezone;\n  const today = tzParts(nowMs, tz).date;\n  const last = addDays(today, config.booking_window_days);\n  const dur = config.viewing_minutes * 60000;\n  const buf = config.buffer_minutes * 60000;\n  const blocks = busy.map((b) => [Date.parse(b.start) - buf, Date.parse(b.end) + buf]);\n  const out = [];\n  for (let i = 0; i < days && out.length < limit; i++) {\n    const date = addDays(from, i);\n    if (date > last) break;\n    const hours = config.viewing_hours[weekdayOf(date)];\n    if (!hours) continue;\n    const open = zonedToMs(date, hours[0], tz);\n    const close = zonedToMs(date, hours[1], tz);\n    for (let t = open; t + dur <= close && out.length < limit; t += 30 * 60000) {\n      if (t < nowMs + config.lead_time_minutes * 60000) continue;\n      if (blocks.some(([s, e]) => t < e && t + dur > s)) continue;\n      out.push(t);\n      t += dur - 30 * 60000; // следующий вариант — после этого просмотра, без пересечений\n    }\n  }\n  return out;\n}\n\nconst localIso = (ms, tz) => {\n  const p = tzParts(ms, tz);\n  return `${p.date}T${p.time}`;\n};\n\nconst { config, input } = $('Config').first().json;\nconst read = $input.first().json;\nif (read.error) {\n  return [{ json: { ok: false, result: { ok: false, service_error: String(read.error.message || read.error).slice(0, 300), note: 'Таблица лидов недоступна. Продолжай разговор, но не говори, что данные сохранены.' } } }];\n}\nconst rows = sheetRows(read.values);\nconst now = new Date().toISOString();\nconst sessionPhone = input.customer_phone || '';\nlet lead = findLead(rows, input.session_id, input.phone || sessionPhone);\nconst isNew = !lead;\nlead = lead ? { ...lead } : {\n  created: now, lead_id: 'RL-' + Date.now().toString(36).toUpperCase().slice(-6), session_id: input.session_id, channel: input.channel,\n  source: input.source || input.channel, stage: 'new', follow_ups: '0', currency: config.currency,\n  _row: rows.length + 2,\n};\n\n// Поле обновляется, только если агент его прислал; пустое — оставляем как было.\nconst pick = (v, allowed) => {\n  const s = norm(v);\n  if (!s || s === 'unknown') return '';\n  return allowed ? (allowed.includes(s) ? s : '') : String(v).trim().slice(0, 200);\n};\nconst set = (key, v) => { if (v) lead[key] = v; };\nset('deal_type', pick(input.deal_type, ['buy', 'rent']));\nset('property_type', pick(input.property_type, ['apartment', 'house', 'commercial', 'land', 'any']));\nset('area', pick(input.area));\nset('rooms', pick(input.rooms));\nif (num(input.budget_max)) lead.budget_max = String(num(input.budget_max));\nset('currency', pick(input.currency));\nset('timeline', pick(input.timeline, ['now', '1-3m', '3-6m', 'later']));\nset('mortgage', pick(input.mortgage, ['cash', 'preapproved', 'needed', 'no']));\nset('name', pick(input.name) || pick(input.customer_name));\nconst phone = digits(input.phone || sessionPhone);\nif (phone.length >= 9) lead.phone = '+' + phone.replace(/^0/, config.phone_country || '380');\nset('email', pick(input.email));\nif (input.channel === 'telegram') set('telegram', input.customer_contact || input.session_id);\nif (input.notes) lead.notes = [lead.notes, String(input.notes).slice(0, 300)].filter(Boolean).join(' | ').slice(-1000);\n\n// Балл: видимые правила, не мнение модели.\nconst reasons = [];\nlet score = 0;\nconst add = (p, why) => { score += p; reasons.push(`${why} +${p}`); };\nif (lead.phone || lead.telegram || lead.email) add(15, 'есть контакт');\nif (lead.deal_type) add(5, 'понятна цель');\nif (lead.area) add(10, 'район');\nif (lead.rooms || (lead.property_type && lead.property_type !== 'any')) add(10, 'тип или комнаты');\nif (num(lead.budget_max)) add(20, 'бюджет');\nif (lead.timeline === 'now') add(20, 'ищет сейчас');\nelse if (lead.timeline === '1-3m') add(10, 'в ближайшие 3 месяца');\nelse if (lead.timeline === '3-6m') add(5, 'через 3–6 месяцев');\nif (['cash', 'no', 'preapproved'].includes(lead.mortgage) || lead.deal_type === 'rent') add(20, lead.deal_type === 'rent' ? 'аренда без ипотеки' : 'деньги готовы');\nelse if (lead.mortgage === 'needed') add(5, 'нужна ипотека');\nlead.score = String(score);\nlead.segment = score >= config.hot_score ? 'hot' : score >= 40 ? 'warm' : 'cold';\n\n// Риелтор: закреплённый — остаётся; новый — по району и цели, иначе по очереди (по хэшу диалога).\nif (!lead.agent_id) {\n  const agents = config.agents || [];\n  const byDeal = agents.filter((a) => !lead.deal_type || !a.deal_types?.length || a.deal_types.includes(lead.deal_type));\n  const byArea = byDeal.filter((a) => lead.area && (a.areas || []).some((x) => norm(lead.area).includes(norm(x)) || norm(x).includes(norm(lead.area))));\n  const pool = byArea.length ? byArea : byDeal.length ? byDeal : agents;\n  let h = 0;\n  for (const ch of String(lead.session_id)) h = (h * 31 + ch.charCodeAt(0)) >>> 0;\n  if (pool.length && lead.deal_type) lead.agent_id = pool[h % pool.length].id;\n}\nif (['new', ''].includes(lead.stage || '') && lead.deal_type && lead.area && num(lead.budget_max)) lead.stage = 'qualified';\nlead.last_contact = now;\n\nconst missing = [];\nif (!lead.deal_type) missing.push('покупка или аренда');\nif (!lead.area) missing.push('район');\nif (!num(lead.budget_max)) missing.push('бюджет');\nif (!lead.rooms && !lead.property_type) missing.push('комнат или тип жилья');\nif (!lead.timeline) missing.push('когда планирует');\nif (lead.deal_type === 'buy' && !lead.mortgage) missing.push('наличные или ипотека');\nif (!lead.phone && input.channel !== 'telegram') missing.push('телефон');\n\nconst agent = (config.agents || []).find((a) => a.id === lead.agent_id);\nlet alert_html = '';\nlet chat_id = '';\nif (lead.segment === 'hot' && !lead.notified) {\n  lead.notified = now;\n  chat_id = (agent && agent.chat_id) || config.team_chat_id;\n  alert_html = [\n    `<b>🔥 Горячий лид ${score}/100</b>${agent ? ` → ${escapeHtml(agent.name)}` : ''}`,\n    `${escapeHtml(lead.name || 'Без имени')} · ${escapeHtml(lead.phone || lead.telegram || lead.email || 'контакт не указан')}`,\n    `${lead.deal_type === 'rent' ? 'Аренда' : 'Покупка'} · ${escapeHtml(lead.area || '')} · ${escapeHtml(lead.rooms || lead.property_type || '')} · до ${escapeHtml(lead.budget_max || '?')} ${escapeHtml(lead.currency || '')}`,\n    `Срок: ${escapeHtml(lead.timeline || '?')} · Ипотека: ${escapeHtml(lead.mortgage || '?')}`,\n    `<code>${escapeHtml(lead.lead_id)}</code>`,\n  ].join('\\n');\n}\n\nconst row = lead._row;\nreturn [{ json: {\n  ok: true,\n  row,\n  range: leadRange(row),\n  values: leadValues(lead),\n  alert_html,\n  chat_id,\n  result: {\n    ok: true,\n    lead_id: lead.lead_id,\n    new_lead: isNew,\n    segment: lead.segment,\n    stage: lead.stage,\n    agent: agent ? agent.name : '',\n    missing,\n    score_reasons: reasons,\n    note: missing.length\n      ? `Сохранено. Не хватает: ${missing.join(', ')}. Спроси одно-два из этого, не всё сразу. Балл и сегмент клиенту не называй.`\n      : 'Анкета заполнена. Предложи подобрать объекты (search_listings). Балл и сегмент клиенту не называй.',\n  },\n} }];\n"
      }
