        "jsCode": "// ================= НАСТРОЙКИ =================\n// Меняйте только значения справа от двоеточия. Подробно — docs/02-setup.md.\nconst config = {\n  // ---- кто пишет ----\n  company: 'Название компании',\n  sender_name: 'Анна, финансовый отдел',\n  payment_details: 'Оплатить можно по реквизитам в счёте или по ссылке: https://example.com/pay',\n  timezone_offset_hours: 2,\n\n  // ---- где данные ----\n  spreadsheet_id: 'ВСТАВЬТЕ_ID_ТАБЛИЦЫ',   // листы Invoices, Drafts, Activity\n\n  // ---- кто одобряет ----\n  // ID Telegram-чатов, которым можно нажимать кнопки и писать команды. Первый получает черновики и отчёт.\n  approver_chat_ids: ['ВСТАВЬТЕ_ID_ЧАТА'],\n\n  // ---- письма ----\n  email: {\n    from: 'Финансовый отдел <billing@example.com>',\n    reply_to: 'billing@example.com',\n  },\n\n  // ---- последовательность напоминаний ----\n  // day — сколько дней просрочки, tone — тон письма. Шаг отправляется, только если предыдущий уже ушёл.\n  sequence: [\n    { day: 1, tone: 'friendly' },    // дружеское: «возможно, письмо потерялось»\n    { day: 7, tone: 'firm' },        // деловое: конкретная просьба и срок\n    { day: 14, tone: 'escalate' },   // настойчивое: предложить созвон, график платежей\n    { day: 30, tone: 'final' },      // последнее: что будет дальше — только то, что разрешено ниже\n  ],\n  min_gap_days: 3,                   // не чаще одного письма по счёту за столько дней\n  max_drafts_per_run: 20,\n\n  // ---- риск ----\n  high_amount: 5000,                 // счета от этой суммы — выше риск\n\n  // ---- что можно упоминать в письмах ----\n  // По умолчанию письма не грозят: никаких судов, коллекторов, штрафов.\n  allow_late_fee: false,             // true — можно упомянуть пени из договора\n  late_fee_text: '',                 // точная формулировка из договора, например «0,1% за день просрочки по п. 5.2»\n  allow_collection: false,           // true — в последнем письме можно упомянуть передачу долга агентству\n  collection_text: '',               // точная формулировка\n\n  // ---- предпросмотр для evals ----\n  preview_token: '',                 // пусто — вебхук предпросмотра выключен\n};\n\nreturn [{ json: { config, input: $input.first().json } }];\n"
