    {
      "id": "de2d495e-84e0-5faa-abd1-f9ddc46d1b75",
      "name": "Check Draft",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        740,
        -100
      ],
      "parameters": {
        "jsCode": "// Check Draft: проверяет ответ модели. Что не прошло проверку — заменяется шаблоном,\n// риск по правилам не может понизиться, письмо получает реквизиты и подпись из Config.\n// ---- shared text helpers (inlined into Code nodes by the builder) ----\nconst STOP = new Set(('и в во не что он на я с со как а то все она так его но да ты к у же вы за бы по только ее мне было вот от меня еще нет о из ему теперь когда даже ну вдруг ли если уже или ни быть был него до вас нибудь опять уж вам ведь там потом себя ничего ей может они тут где есть надо ней для мы тебя их чем была сам чтоб без будто чего раз тоже себе под будет ж тогда кто этот того потому этого какой совсем ним здесь этом один почти мой тем чтобы нее сейчас были куда зачем всех никогда можно при наконец два об другой хоть после над больше тот через эти нас про всего них какая много разве три эту моя впрочем хорошо свою этой перед иногда лучше чуть том нельзя такой им более всегда конечно всю между это мой мою мое здравствуйте добрый день привет пожалуйста подскажите скажите хочу хотел хотела можно ли вы ваш ваша ваши the a an and or of to in on for is are be it this that with as at by from i you we my our your me do does how what can could please hi hello').split(' '));\n\nfunction stem(word) {\n  let w = word.toLowerCase().replace(/ё/g, 'е');\n  if (/^[a-z]+$/.test(w)) return w.replace(/(ing|ed|es|s)$/, '').slice(0, 7);\n  w = w.replace(/(ями|ами|иями|ией|ией|ого|ему|ому|ыми|ими|его|ая|яя|ое|ее|ие|ые|ой|ей|ий|ый|ов|ев|ам|ям|ах|ях|ом|ем|ую|юю|ть|ти|ешь|ет|ем|ете|ют|ут|ит|им|ите|ат|ят|ла|ло|ли|ся|сь|а|я|о|е|и|ы|у|ю|ь|й)$/, '');\n  return w.slice(0, 6);\n}\n\nfunction terms(text) {\n  return (String(text).toLowerCase().match(/[\\p{L}\\p{N}]+/gu) || [])\n    .filter((w) => w.length > 1 && !STOP.has(w))\n    .map(stem)\n    .filter((w) => w.length > 1);\n}\n\nfunction escapeHtml(text) {\n  return String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n}\n\nfunction sheetRows(values) {\n  const [head = [], ...rows] = values || [];\n  const keys = head.map((h) => String(h).trim().toLowerCase());\n  return rows.map((r, i) => Object.fromEntries([['_row', i + 2], ...keys.map((k, j) => [k, String(r[j] ?? '').trim()])]));\n}\n\n// ---- счета: даты, правила остановки, риск по правилам ----\nconst DAY = 86400000;\n\nfunction today(config, now) {\n  return new Date(now + config.timezone_offset_hours * 3600000).toISOString().slice(0, 10);\n}\n\nfunction parseDate(v) {\n  const s = String(v || '').trim();\n  let m = /^(\\d{4})-(\\d{2})-(\\d{2})/.exec(s);\n  if (m) return `${m[1]}-${m[2]}-${m[3]}`;\n  m = /^(\\d{1,2})[./](\\d{1,2})[./](\\d{4})$/.exec(s);\n  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;\n  return '';\n}\n\nfunction daysBetween(a, b) {\n  return Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / DAY);\n}\n\nfunction num(v) {\n  const n = parseFloat(String(v ?? '').replace(/[\\s ]/g, '').replace(',', '.'));\n  return Number.isFinite(n) ? n : 0;\n}\n\nfunction yesish(v) {\n  return /^(1|true|yes|да|y)$/i.test(String(v ?? '').trim());\n}\n\nfunction fmtAmount(n) {\n  const [i, d] = n.toFixed(2).split('.');\n  return i.replace(/\\B(?=(\\d{3})+(?!\\d))/g, ' ') + (d === '00' ? '' : ',' + d);\n}\n\n/** Invoices: invoice_id | client | contact_name | email | amount | currency | issued | due | status | paid_at | promise_date | disputed | paused | last_contact | stage | notes */\nconst INVOICE_COLS = ['invoice_id', 'client', 'contact_name', 'email', 'amount', 'currency', 'issued', 'due', 'status', 'paid_at', 'promise_date', 'disputed', 'paused', 'last_contact', 'stage', 'notes'];\n\nfunction invoices(values) {\n  return sheetRows(values).filter((r) => r.invoice_id).map((r) => ({\n    ...r,\n    amount_n: num(r.amount),\n    due_d: parseDate(r.due),\n    paid_d: parseDate(r.paid_at),\n    promise_d: parseDate(r.promise_date),\n    last_d: parseDate(r.last_contact),\n    stage_n: Number(r.stage || 0),\n    closed: /^(paid|оплачен|cancelled|отменён|отменен|written.off|списан)/i.test(r.status || '') || Boolean(parseDate(r.paid_at)),\n  }));\n}\n\nfunction invoiceRow(inv) {\n  return INVOICE_COLS.map((k) => String(inv[k] ?? ''));\n}\n\n/** Why an invoice must not be chased right now; '' — can be chased. */\nfunction stopReason(inv, day) {\n  if (inv.closed) return 'оплачен или закрыт';\n  if (yesish(inv.disputed)) return 'клиент оспаривает счёт';\n  if (yesish(inv.paused)) return 'напоминания на паузе';\n  if (inv.promise_d && inv.promise_d >= day) return `клиент обещал оплатить до ${inv.promise_d}`;\n  if (!inv.email) return 'нет email';\n  if (!inv.due_d) return 'нет даты оплаты';\n  return '';\n}\n\n/** Deterministic risk: low / medium / high with reasons in words. */\nfunction ruleRisk(inv, all, day, config) {\n  const reasons = [];\n  let score = 0;\n  const overdue = daysBetween(inv.due_d, day);\n  if (overdue > 60) { score += 3; reasons.push(`просрочка ${overdue} дн.`); }\n  else if (overdue > 30) { score += 2; reasons.push(`просрочка ${overdue} дн.`); }\n  else if (overdue > 7) { score += 1; reasons.push(`просрочка ${overdue} дн.`); }\n  if (inv.amount_n >= config.high_amount) { score += 1; reasons.push(`крупная сумма (${fmtAmount(inv.amount_n)} ${inv.currency})`); }\n  const late = all.filter((x) => x.client === inv.client && x.invoice_id !== inv.invoice_id && x.paid_d && x.due_d && x.paid_d > x.due_d).length;\n  if (late >= 2) { score += 1; reasons.push(`клиент уже ${late} раза платил с опозданием`); }\n  if (inv.promise_d && inv.promise_d < day) { score += 2; reasons.push(`обещание оплатить до ${inv.promise_d} не выполнено`); }\n  if (inv.stage_n >= 3) { score += 1; reasons.push(`уже ${inv.stage_n} напоминания без оплаты`); }\n  const risk = score >= 4 ? 'high' : score >= 2 ? 'medium' : 'low';\n  return { risk, reasons: reasons.length ? reasons : ['небольшая просрочка, раньше проблем не было'], overdue, late_count: late };\n}\n\nconst RISK_ORDER = { low: 0, medium: 1, high: 2 };\n\nconst TONE_RU = { friendly: 'дружеский', firm: 'деловой', escalate: 'настойчивый', final: 'последнее напоминание' };\n\n/** What the model sees about one invoice. */\nfunction factsText(p, config) {\n  const allowed = [];\n  if (config.allow_late_fee && config.late_fee_text) allowed.push(`пени по договору: ${config.late_fee_text}`);\n  if (config.allow_collection && config.collection_text && p.final_step) allowed.push(`передача долга: ${config.collection_text}`);\n  return [\n    `Счёт: ${p.invoice_id}`,\n    `Клиент: ${p.client}${p.contact_name ? ', контакт: ' + p.contact_name : ''}`,\n    `Сумма: ${p.amount_text}`,\n    `Выставлен: ${p.issued || 'не указано'}; срок оплаты: ${p.due}; просрочка: ${p.overdue} дн.`,\n    `Письмо №${p.step} из ${config.sequence.length}, тон: ${p.tone} (${TONE_RU[p.tone] || p.tone})${p.final_step ? ', последнее в последовательности' : ''}`,\n    p.broken_promise ? 'Клиент обещал оплатить к дате, которая уже прошла.' : '',\n    p.late_count ? `Раньше клиент платил с опозданием: ${p.late_count} раз(а).` : 'Раньше просрочек по другим счетам не было.',\n    `Риск по правилам: ${p.rule_risk} — ${p.rule_reasons.join('; ')}`,\n    p.notes ? `Заметки менеджера: ${p.notes}` : 'Заметок нет.',\n    allowed.length ? `Разрешено упомянуть дословно: ${allowed.join('; ')}` : 'Упоминать пени, суд, коллекторов и любые санкции нельзя.',\n  ].filter(Boolean).join('\\n');\n}\n\nconst { config } = $('Config').first().json;\nconst plans = ($('Preview Plan').isExecuted ? $('Preview Plan') : $('Plan Invoices')).all().map((i) => i.json);\nconst answers = $input.all().map((i) => i.json);\n\n// \\b в JS не видит границу кириллического слова — поэтому (?<![а-яё]) и (?![а-яё])\nconst THREATS = [/(?<![а-яё])суд(?![а-яё])|(?<![а-яё])судеб|(?<![а-яё])иск(?![а-яё])|(?<![а-яё])исков|юрист|адвокат|коллектор|арбитраж|прокурат|полици|штраф|(?<![а-яё])пен(я|и|ю|ей|ям)(?![а-яё])|неустойк|кредитн[а-я]* истори|санкци|court|lawsuit|lawyer|attorney|collection agenc|debt collector|penalt|late fee|credit score/i];\nconst SHAMING = /(игнорир|нарушил|безответствен|недобросовест|вы обязаны немедленно)/i;\nconst DISCOUNT = /(скидк|рассрочк|списываем|прощаем|discount|write.?off)/i;\n\nfunction parse(text) {\n  const t = String(text || '').trim().replace(/^```(?:json)?\\s*/i, '').replace(/\\s*```$/, '');\n  const s = t.indexOf('{');\n  const e = t.lastIndexOf('}');\n  if (s < 0 || e <= s) return null;\n  try { return JSON.parse(t.slice(s, e + 1)); } catch { return null; }\n}\n\nfunction amountIn(body, p) {\n  const digits = String(body).replace(/[\\s ]/g, '');\n  const whole = String(Math.trunc(p.amount));\n  return digits.includes(whole) || digits.includes(fmtAmount(p.amount).replace(/\\s/g, ''));\n}\n\nfunction template(p) {\n  const hi = p.contact_name ? `${p.contact_name}, добрый день!` : 'Добрый день!';\n  const t = {\n    friendly: `Напоминаем о счёте ${p.invoice_id} на ${p.amount_text}: срок оплаты был ${p.due}. Возможно, письмо затерялось — подскажите, пожалуйста, всё ли в порядке и когда планируете оплату?`,\n    firm: `Счёт ${p.invoice_id} на ${p.amount_text} просрочен на ${p.overdue} дн. (срок был ${p.due}). Просим оплатить его или сообщить дату оплаты в ответ на это письмо.`,\n    escalate: `Счёт ${p.invoice_id} на ${p.amount_text} не оплачен уже ${p.overdue} дн. Давайте найдём решение: можем созвониться и обсудить удобный график. Пожалуйста, ответьте в ближайшие дни.`,\n    final: `Это последнее напоминание о счёте ${p.invoice_id} на ${p.amount_text}, срок оплаты которого истёк ${p.due}. Пожалуйста, оплатите счёт или свяжитесь с нами, чтобы договориться.`,\n  }[p.tone] || '';\n  return { subject: `Счёт ${p.invoice_id}: напоминание об оплате`, body: `${hi}\\n\\n${t}` };\n}\n\nconst allowedText = [config.allow_late_fee && config.late_fee_text, config.allow_collection && config.collection_text].filter(Boolean);\n\nreturn plans.map((p, i) => {\n  const flags = [];\n  const a = parse(answers[i]?.text ?? answers[i]?.output);\n  let risk = p.rule_risk;\n  let reasons = [...p.rule_reasons];\n  let subject = '';\n  let body = '';\n  if (!a) flags.push('template:not_json');\n  else {\n    if (['low', 'medium', 'high'].includes(a.risk)) {\n      if (RISK_ORDER[a.risk] > RISK_ORDER[risk]) {\n        risk = a.risk;\n        flags.push('risk_raised_by_model');\n      }\n      if (Array.isArray(a.reasons)) reasons = [...reasons, ...a.reasons.map(String).slice(0, 4).map((r) => 'модель: ' + r.slice(0, 160))];\n    } else flags.push('bad_risk');\n    subject = String(a.subject || '').replace(/\\s+/g, ' ').trim();\n    body = String(a.body || '').trim();\n    let why = '';\n    if (!subject || subject.length > 120) why = 'subject';\n    else if (!body || body.length < 40) why = 'empty';\n    else if (body.length > 2000) why = 'too_long';\n    else if (!body.includes(p.invoice_id)) why = 'no_invoice_id';\n    else if (!amountIn(body, p)) why = 'no_amount';\n    else {\n      // разрешённую формулировку из Config вырезаем перед проверкой — остальное грозить не должно\n      let check = body;\n      for (const t of allowedText) check = check.split(t).join('');\n      if (THREATS.some((r) => r.test(check + ' ' + subject))) why = 'threat';\n      else if (SHAMING.test(body)) why = 'shaming';\n      else if (DISCOUNT.test(body)) why = 'discount';\n      else if (/https?:\\/\\/|www\\./i.test(body)) why = 'link';\n    }\n    if (why) flags.push('template:' + why);\n  }\n  if (flags.some((f) => f.startsWith('template:'))) ({ subject, body } = template(p));\n  const full = [body, '', config.payment_details, '', 'С уважением,', config.sender_name, config.company].join('\\n');\n  const draft_id = 'D-' + Date.now().toString(36).toUpperCase().slice(-5) + i.toString(36).toUpperCase() + Math.floor(Math.random() * 36 ** 2).toString(36).toUpperCase().padStart(2, '0');\n  return { json: { ...p, draft_id, risk, reasons, subject, body: full, flags } };\n});\n"
      }
    },
