ad = [], ...rows] = values || [];\n  const keys = head.map((h) => String(h).trim().toLowerCase());\n  return rows.map((r, i) => Object.fromEntries([['_row', i + 2], ...keys.map((k, j) => [k, String(r[j] ?? '').trim()])]));\n}\n\n// ---- поиск по строкам листа: слова с учётом окончаний, редкие весят больше ----\nfunction rank(rows, query, headFields, bodyFields, limit) {\n  const q = [...new Set(terms(query))];\n  if (!q.length || !rows.length) return [];\n  const docs = rows.map((r) => ({ r, head: terms(headFields.map((f) => r[f] || '').join(' ')), body: terms(bodyFields.map((f) => r[f] || '').join(' ')) }));\n  const df = {};\n  for (const d of docs) for (const t of new Set([...d.head, ...d.body])) df[t] = (df[t] || 0) + 1;\n  const idf = (t) => Math.log(1 + docs.length / (df[t] || 0.5));\n  const total = q.reduce((a, t) => a + idf(t), 0);\n  return docs.map((d) => {\n    const head = new Set(d.head);\n    const body = new Set(d.body);\n    let hit = 0;\n    for (const t of q) hit += head.has(t) ? idf(t) : body.has(t) ? idf(t) * 0.6 : 0;\n    return { row: d.r, score: Math.round((hit / total) * 100) / 100 };\n  }).filter((x) => x.score > 0).sort((x, y) => y.score - x.score).slice(0, limit);\n}\n\nconst { input } = $('Config').first().json;\nconst feed = $input.first().json;\nif (feed.error) {\n  return [{ json: { result: { ok: false, service_error: String(feed.error.message || feed.error).slice(0, 300),\n    note: 'Одобренные ответы недоступны. Не приводи цифр, кейсов и гарантий — предложи звонок с менеджером.' } } }];\n}\nconst rows = sheetRows(feed.values).filter((r) => r.approved_answer);\nconst found = rank(rows, input.topic, ['topic', 'tags'], ['approved_answer'], 3).filter((x) => x.score >= 0.25);\nreturn [{ json: { result: found.length\n  ? { ok: true, found: true, facts: found.map((x) => ({ id: x.row.id, topic: x.row.topic, approved_answer: x.row.approved_answer })),\n      note: 'Опирайся только на эти формулировки: цифры, кейсы и условия из них можно назы