          "parse_mode": "HTML"
        }
      },
      "id": "27fd1503-3826-5e25-a5c9-81c8260fb00e",
      "name": "Send Alert",
      "type": "n8n-nodes-base.telegram",
      "typeVersion": 1.2,
      "position": [
        -40,
        0
      ],
      "retryOnFail": true,
      "maxTries": 3,
      "waitBetweenTries": 2000,
      "credentials": {
        "telegramApi": {
          "id": "REPLACE_ME",
          "name": "Telegram bot"
        }
      }
    }
  ],
  "connections": {
    "On Error": {
