{
  "model": "REPLACE_WITH_MODEL",
  "start_speaker": "agent",
  "begin_message": "Здравствуйте! Это служба доставки «{{business_name}}», я {{agent_name}}, виртуальный помощник. Звоню по вашему заказу {{order_id}}.",
  "general_prompt": "ВСТАВЬТЕ СЮДА ТЕКСТ ИЗ prompts/system-prompt.ru.md",
  "general_tools": [
    {
      "type": "end_call",
      "name": "end_call",
      "description": "Завершить звонок, когда вопрос решён и клиент попрощался."
    },
    {
      "type": "transfer_call",
      "name": "transfer_to_operator",
      "description": "Перевести на оператора: состав заказа, отмена, оплата, жалоба, просьба о человеке.",
      "transfer_destination": {
        "type": "predefined",
        "number": "REPLACE_WITH_ADMIN_NUMBER_E164"
      },
      "transfer_option": {
        "type": "cold_transfer",
        "show_transferee_as_caller": false
      }
    },
    {
      "type": "custom",
      "name": "find_order",
      "description": "Найти активные заказы клиента по номеру телефона: дата и интервал доставки, адрес, статус. Вызывай в начале каждого разговора о заказе.",
      "url": "https://REPLACE-N8N-HOST/webhook/voice-tools",
      "method": "POST",
      "headers": {
        "X-Voice-Secret": "REPLACE_WITH_SECRET"
      },
      "parameters": {
        "type": "object",
        "properties": {
          "customer_phone": {
            "type": "string",
            "description": "Телефон клиента цифрами, как он его продиктовал. При исходящем звонке — номер, на который звоним."
          },
          "order_id": {
            "type": "string",
            "description": "Номер заказа, если клиент его назвал."
          }
        },
        "required": [
          "customer_phone"
        ]
      },
      "speak_during_execution": true,
      "speak_after_execution": true,
      "timeout_ms": 15000
    },
    {
      "type": "custom",
      "name": "confirm_delivery",
      "description": "Отметить, что клиент подтвердил дату, интервал и адрес доставки. Только после явного «да».",
      "url": "https://REPLACE-N8N-HOST/webhook/voice-tools",
      "method": "POST",
      "headers": {
        "X-Voice-Secret": "REPLACE_WITH_SECRET"
      },
      "parameters": {
        "type": "object",
        "properties": {
          "order_id": {
            "type": "string",
            "description": "Номер заказа из ответа find_order."
          },
          "customer_phone": {
            "type": "string",
            "description": "Телефон клиента цифрами, как он его продиктовал. При исходящем звонке — номер, на который звоним."
          },
          "consent": {
            "type": "boolean",
            "description": "true — только после того, как клиент подтвердил повторённые тобой данные."
          }
        },
        "required": [
          "order_id",
          "customer_phone",
          "consent"
        ]
      },
      "speak_during_execution": true,
      "speak_after_execution": true,
      "timeout_ms": 15000
    },
    {
      "type": "custom",
      "name": "update_address",
      "description": "Изменить или уточнить адрес доставки. Передавай только то, что меняется. Новую улицу — вместе с номером дома, город — только из зоны доставки.",
      "url": "https://REPLACE-N8N-HOST/webhook/voice-tools",
      "method": "POST",
      "headers": {
        "X-Voice-Secret": "REPLACE_WITH_SECRET"
      },
      "parameters": {
        "type": "object",
        "properties": {
          "order_id": {
            "type": "string",
            "description": "Номер заказа из ответа find_order."
          },
          "customer_phone": {
            "type": "string",
            "description": "Телефон клиента цифрами, как он его продиктовал. При исходящем звонке — номер, на который звоним."
          },
          "city": {
            "type": "string",
            "description": "Город, если меняется."
          },
          "address": {
            "type": "string",
            "description": "Улица и дом, если меняются: «проспект Победы, 12»."
          },
          "apartment": {
            "type": "string",
            "description": "Квартира или офис."
          },
          "entrance": {
            "type": "string",
            "description": "Подъезд."
          },
          "floor": {
            "type": "string",
            "description": "Этаж."
          },
          "intercom": {
            "type": "string",
            "description": "Код домофона."
          },
