            "type": "string",
            "description": "Подсказка курьеру словами клиента: «позвонить за 15 минут», «вход со двора»."
          },
          "consent": {
            "type": "boolean",
            "description": "true — только после того, как клиент подтвердил повторённые тобой данные."
          }
        },
        "required": [
          "order_id",
          "customer_phone",
          "consent"
        ]
      },
      "speak_during_execution": true,
      "speak_after_execution": true,
      "timeout_ms": 15000
    },
    {
      "type": "custom",
      "name": "check_windows",
      "description": "Найти свободные интервалы доставки на дату. Вызывай перед тем, как предлагать время. Никогда не называй интервал без этого вызова.",
      "url": "https://REPLACE-N8N-HOST/webhook/voice-tools",
      "method": "POST",
      "headers": {
        "X-Voice-Secret": "REPLACE_WITH_SECRET"
      },
      "parameters": {
        "type": "object",
        "properties": {
          "order_id": {
            "type": "string",
            "description": "Номер заказа из ответа find_order."
          },
          "customer_phone": {
            "type": "string",
            "description": "Телефон клиента цифрами, как он его продиктовал. При исходящем звонке — номер, на который звоним."
          },
          "date": {
            "type": "string",
            "description": "Дата: ГГГГ-ММ-ДД, либо today, tomorrow, день недели (mon, tue, wed, thu, fri, sat, sun), либо +N дней. Не вычисляй дату сам."
          }
        },
        "required": [
          "order_id",
          "customer_phone",
          "date"
        ]
      },
      "speak_during_execution": true,
      "speak_after_execution": true,
      "timeout_ms": 15000
    },
    {
      "type": "custom",
      "name": "change_window",
      "description": "Перенести доставку на другую дату или интервал. Сначала check_windows, затем повтори клиенту выбор и получи «да».",
      "url": "https://REPLACE-N8N-HOST/webhook/voice-tools",
      "method": "POST",
      "headers": {
        "X-Voice-Secret": "REPLACE_WITH_SECRET"
      },
      "parameters": {
        "type": "object",
        "properties": {
          "order_id": {
            "type": "string",
            "description": "Номер заказа из ответа find_order."
          },
          "customer_phone": {
            "type": "string",
            "description": "Телефон клиента цифрами, как он его продиктовал. При исходящем звонке — номер, на который звоним."
          },
          "date": {
            "type": "string",
            "description": "date выбранного интервала из ответа check_windows."
          },
          "window_id": {
            "type": "string",
            "description": "window_id выбранного интервала из ответа check_windows."
          },
          "consent": {
            "type": "boolean",
            "description": "true — только после того, как клиент подтвердил повторённые тобой данные."
          }
        },
        "required": [
          "order_id",
          "customer_phone",
          "date",
          "window_id",
          "consent"
        ]
      },
      "speak_during_execution": true,
      "speak_after_execution": true,
      "timeout_ms": 15000
    },
    {
      "type": "custom",
      "name": "request_callback",
      "description": "Передать оператору: изменить состав заказа, отменить заказ, оплата и возврат, жалоба, адрес вне зоны доставки, сбой, вопрос без ответа.",
      "url": "https://REPLACE-N8N-HOST/webhook/voice-tools",
      "method": "POST",
      "headers": {
        "X-Voice-Secret": "REPLACE_WITH_SECRET"
      },
      "parameters": {
        "type": "object",
        "properties": {
          "customer_name": {
            "type": "string",
            "description": "Имя клиента."
          },
          "customer_phone": {
            "type": "string",
            "description": "Телефон клиента цифрами, как он его продиктовал. При исходящем звонке — номер, на который звоним."
          },
          "order_id": {
            "type": "string",
            "description": "Номер заказа, если известен."
          },
          "topic": {
            "type": "string",
            "description": "О чём просят, одной фразой: «добавить товар», «отменить заказ»."
          },
          "urgency": {
            "type": "string",
            "description": "Срочность словами: сегодня, до доставки, не срочно."
          },
          "details": {
            "type": "string",
            "description": "Что важно знать оператору до звонка."
          }
        },
        "required": [
          "customer_name",
          "customer_phone",
          "topic"
        ]
      },
      "speak_during_execution": true,
      "speak_after_execution": true,
      "timeout_ms": 15000
    }
  ],
  "default_dynamic_variables": {
    "business_name": "REPLACE",
    "agent_name": "REPLACE",
    "language": "русский",
    "recording_notice": "",
    "order_id": "",
    "customer_name": "",
    "delivery": "",
    "address": ""
  }
}

