      "parameters": {
        "jsCode": "// Mark Calls — counts the attempt on each order and builds one write for the sheet.\nconst cfg = $('Config').first().json;\nconst picked = $('Pick Calls').all();\nconst answers = $input.all();\n// ---- time helpers (business time zone, no libraries) ----\nconst TZ = cfg.timezone;\nconst MIN = 60000;\nconst DAY = 24 * 60 * MIN;\nconst pad = (n) => String(n).padStart(2, '0');\nconst nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());\nfunction offsetMin(utcMs) {\n  const parts = new Intl.DateTimeFormat('en-US', {\n    timeZone: TZ, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit',\n    hour: '2-digit', minute: '2-digit', second: '2-digit',\n  }).formatToParts(new Date(utcMs));\n  const p = {};\n  for (const part of parts) p[part.type] = part.value;\n  return Math.round((Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute, +p.second) - utcMs) / MIN);\n}\nfunction localToUtc(y, mo, d, h, mi) {\n  const guess = Date.UTC(y, mo - 1, d, h, mi);\n  const first = guess - offsetMin(guess) * MIN;\n  return guess - offsetMin(first) * MIN; // second pass settles days when clocks change\n}\nfunction local(ms) {\n  const shifted = new Date(ms + offsetMin(ms) * MIN);\n  return {\n    y: shifted.getUTCFullYear(), mo: shifted.getUTCMonth() + 1, d: shifted.getUTCDate(),\n    h: shifted.getUTCHours(), mi: shifted.getUTCMinutes(), dow: shifted.getUTCDay(),\n  };\n}\nconst localIso = (ms) => { const t = local(ms); return `${t.y}-${pad(t.mo)}-${pad(t.d)}T${pad(t.h)}:${pad(t.mi)}`; };\nconst localDate = (ms) => localIso(ms).slice(0, 10);\nconst dayStart = (dateText) => { const m = /^(\\d{4})-(\\d{2})-(\\d{2})/.exec(dateText); return localToUtc(+m[1], +m[2], +m[3], 0, 0); };\nconst at = (dateText, hhmm) => { const m = /^(\\d{4})-(\\d{2})-(\\d{2})/.exec(dateText); const [h, mi] = String(hhmm).split(':').map(Number); return localToUtc(+m[1], +m[2], +m[3], h, mi); };\nconst DOW = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];\nconst spokenDay = (dateText) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', { timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long' }).format(new Date(dayStart(dateText) + 12 * 60 * MIN));\nconst windowOf = (id) => (cfg.windows || []).find((w) => w.id === id);\nconst spokenWindow = (dateText, id) => {\n  const w = windowOf(id);\n  return w ? `${spokenDay(dateText)}, с ${w.start} до ${w.end}` : `${spokenDay(dateText)}, интервал ${id || 'не назначен'}`;\n};\nconst now = nowMs();\nconst head = ($('Read Orders').first().json.values || [[]])[0].map((h) => String(h).trim().toLowerCase());\nconst letter = (i) => (i < 26 ? String.fromCharCode(65 + i) : String.fromCharCode(64 + Math.floor(i / 26)) + String.fromCharCode(65 + (i % 26)));\nconst sheet = `'${String(cfg.sheet_name || 'Orders').replace(/'/g, \"''\")}'`;\nconst cell = (row, col, value) => ({ range: `${sheet}!${letter(head.indexOf(col))}${row}`, values: [[value]] });\nconst data = [];\nconst started = [];\nconst failed = [];\npicked.forEach((item, i) => {\n  const p = item.json;\n  const answer = (answers[i] && answers[i].json) || {};\n  const ok = !answer.error && (answer.id || answer.call_id);\n  (ok ? started : failed).push(p.order_id);\n  const entry = `${localIso(now)} исходящий звонок: ${ok ? 'начат, ' + (answer.id || answer.call_id) : 'не начат — ' + JSON.stringify(answer.error || answer).slice(0, 120)}`;\n  // A call that never started does not use up an attempt; last_call still stops a retry the same day.\n  data.push(cell(p.row, 'calls', String(ok ? p.calls + 1 : p.calls)), cell(p.row, 'last_call', localIso(now)),\n    cell(p.row, 'history', ((p.history ? p.history + '\\n' : '') + entry).slice(-2000)));\n});\nconst report = ['Звонки для подтверждения доставки', `Начато: ${started.length}`, failed.length ? `Не начато: ${failed.length} (${failed.join(', ')})` : ''].filter(Boolean).join('\\n');\nreturn [{ json: { body: { valueInputOption: 'RAW', data }, report } }];\n"
