  "begin_message": "Ресторан «{{business_name}}», здравствуйте. Я {{agent_name}}, виртуальный администратор. Хотите забронировать стол?",
  "general_prompt": "ВСТАВЬТЕ СЮДА ТЕКСТ ИЗ prompts/system-prompt.ru.md",
  "general_tools": [
    {
      "type": "end_call",
      "name": "end_call",
      "description": "Завершить звонок, когда вопрос решён и клиент попрощался."
    },
    {
      "type": "transfer_call",
      "name": "transfer_to_admin",
      "description": "Перевести на администратора: банкет, жалоба, просьба о человеке, вопрос вне рамок.",
      "transfer_destination": {
        "type": "predefined",
        "number": "REPLACE_WITH_ADMIN_NUMBER_E164"
      },
      "transfer_option": {
        "type": "cold_transfer",
        "show_transferee_as_caller": false
      }
    },
    {
      "type": "custom",
      "name": "check_availability",
      "description": "Найти свободный стол на дату для компании. Вызывай перед тем, как предлагать время. Никогда не называй время без этого вызова.",
      "url": "https://REPLACE-N8N-HOST/webhook/voice-tools",
      "method": "POST",
      "headers": {
        "X-Voice-Secret": "REPLACE_WITH_SECRET"
      },
      "parameters": {
        "type": "object",
        "properties": {
          "guests": {
            "type": "integer",
            "description": "Сколько будет гостей, числом. Больше 8 — не бронируй, вызывай request_callback."
          },
          "date": {
            "type": "string",
            "description": "Дата: ГГГГ-ММ-ДД, либо today, tomorrow, день недели (mon, tue, wed, thu, fri, sat, sun), либо +N дней. Не вычисляй дату сам."
          },
          "part_of_day": {
            "type": "string",
            "enum": [
              "any",
              "morning",
              "afternoon",
              "evening"
            ],
            "description": "Время суток, если гость назвал: afternoon — с 12 до 17, evening — после 17."
          },
          "zone": {
            "type": "string",
            "description": "Зона, если гость попросил: hall — основной зал; terrace — терраса. Не спрашивай сам, если гостю всё равно."
          }
        },
        "required": [
          "guests",
          "date"
        ]
      },
      "speak_during_execution": true,
      "speak_after_execution": true,
      "timeout_ms": 15000
    },
    {
      "type": "custom",
      "name": "create_booking",
      "description": "Забронировать стол. Вызывай только после того, как повторил гостю дату, время, число гостей и имя и получил явное «да».",
      "url": "https://REPLACE-N8N-HOST/webhook/voice-tools",
      "method": "POST",
      "headers": {
        "X-Voice-Secret": "REPLACE_WITH_SECRET"
      },
      "parameters": {
        "type": "object",
        "properties": {
          "guests": {
            "type": "integer",
            "description": "Сколько будет гостей, числом. Больше 8 — не бронируй, вызывай request_callback."
          },
          "slot_start": {
            "type": "string",
            "description": "Значение slot_start из ответа check_availability, без изменений."
          },
          "table_id": {
            "type": "string",
            "description": "table_id выбранного времени из ответа check_availability."
          },
          "zone": {
            "type": "string",
            "description": "Зона, если гость попросил: hall — основной зал; terrace — терраса. Не спрашивай сам, если гостю всё равно."
          },
          "customer_name": {
            "type": "string",
            "description": "Имя гостя, как он назвал."
          },
          "customer_phone": {
            "type": "string",
            "description": "Телефон гостя цифрами, как он его продиктовал."
          },
          "occasion": {
            "type": "string",
            "description": "Повод, если гость сам назвал: день рождения, годовщина, деловая встреча."
          },
