const cfg = $('Config').first().json;
const ctx = $('Plan').first().json;
const feed = $input.first().json || {};
// ---- time helpers (business time zone, no libraries) ----
const TZ = cfg.timezone;
const MIN = 60000;
const pad = (n) => String(n).padStart(2, '0');
