    {
      "parameters": {
        "jsCode": "// Config — настройки. Меняйте значения справа от двоеточия.\nreturn [{ json: {\n  \"timezone\": \"Europe/Kyiv\",\n  \"locale\": \"ru-RU\",\n  \"sheets_api_base\": \"https://sheets.googleapis.com/v4\",\n  \"spreadsheet_id\": \"REPLACE_WITH_SPREADSHEET_ID\",\n  \"contacts_sheet\": \"Contacts\",\n  \"graph_api_base\": \"https://graph.facebook.com/v25.0\",\n  \"phone_number_id\": \"REPLACE_WITH_PHONE_NUMBER_ID\",\n  \"team_chat_id\": \"REPLACE_WITH_TEAM_CHAT_ID\",\n  \"followup\": {\n    \"enabled\": true,\n    \"after_hours\": 20,\n    \"text\": \"{name}, подскажите, вопрос ещё актуален? Если удобно, продолжим здесь.\"\n  },\n  \"working_hours\": {\n    \"mon\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"tue\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"wed\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"thu\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"fri\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"sat\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    }\n  }\n} }];\n"
