      "parameters": {
        "jsCode": "// Check Health — new failed runs since the last check, watched workflows that got switched off, and a morning digest.\nconst cfg = $('Config').first().json;\n// ---- shared helpers ----\nconst MIN = 60000;\nconst nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());\nconst digitsOf = (value) => String(value || '').replace(/[^\\d]/g, '');\n// Phones are stored in one international form, so the same person is recognised however they typed it.\nfunction phoneOf(value) {\n  const rules = cfg.phone || {};\n  let d = digitsOf(value);\n  if (d.startsWith('00')) d = d.slice(2);\n  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {\n    d = rules.country_code + d.slice(rules.national_prefix.length);\n  }\n  return d.length >= 9 && d.length <= 15 ? '+' + d : '';\n}\nfunction emailOf(value) {\n  const e = String(value || '').trim().toLowerCase();\n  return /^[^\\s@<>()\",;]+@[^\\s@<>()\",;]+\\.[a-z]{2,}$/.test(e) ? e : '';\n}\nconst localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {\n  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',\n}).format(new Date(ms));\nfunction localParts(ms) {\n  const parts = {};\n  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;\n  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };\n}\nconst sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;\nconst quoteSheet = (name) => \"'\" + String(name).replace(/'/g, \"''\") + \"'\";\nconst plural = (n, one, few, many) => (n % 10 === 1 && n % 100 !== 11 ? one : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? few : many);\nconst pad = (n) => String(n).padStart(2, '0');\nconst stamp = (ms) => { const p = localParts(ms); return `${p.date} ${pad(p.hour)}:${pad(p.minute)}`; };\nconst now = nowMs();\nconst state = $getWorkflowStaticData('global');\nconst workflows = ($('Read Workflows').first().json.data || []);\nconst executions = ($input.first().json.data || []);\nconst names = Object.fromEntries(workflows.map((w) => [String(w.id), w.name]));\nconst ignore = new Set((cfg.ignore_workflow_ids || []).map(String));\nconst watchAll = !(cfg.watch_workflow_ids || []).length;\nconst watched = (id) => !ignore.has(String(id)) && (watchAll || (cfg.watch_workflow_ids || []).map(String).includes(String(id)));\nconst ui = String(cfg.n8n_url || '').replace(/\\/$/, '');\nconst link = (wf, ex) => (ui ? `${ui}/workflow/${wf}/executions/${ex}` : `запуск ${ex}`);\nconst at = (e) => Date.parse(e.stoppedAt || e.startedAt || '') || 0;\nconst since = Number(state.last_check) || now - (cfg.check_every_minutes || 60) * MIN;\nconst out = [];\n\n// New failures, grouped by workflow so a broken workflow is one message, not fifty.\nconst fresh = executions.filter((e) => watched(e.workflowId) && at(e) > since && at(e) <= now);\nif (fresh.length) {\n  const by = {};\n  for (const e of fresh) (by[e.workflowId] = by[e.workflowId] || []).push(e);\n  const lines = Object.entries(by).sort((a, b) => b[1].length - a[1].length).map(([wf, list]) => {\n    const last = list.reduce((x, y) => (at(y) > at(x) ? y : x));\n    return `• ${names[wf] || 'воркфлоу ' + wf} — ${list.length} ${plural(list.length, 'ошибка', 'ошибки', 'ошибок')}, последняя ${stamp(at(last))}\\n  ${link(wf, last.id)}`;\n  });\n  out.push({ send: true, kind: 'errors', text: [`${cfg.client_name ? cfg.client_name + ': ' : ''}ошибки в n8n с ${stamp(since)}`, ...lines].join('\\n') });\n}\n\n// Workflows that must run but are switched off (by a person or by n8n after trigger errors).\nconst must = (cfg.must_be_active || []).map(String);\nconst alerted = new Set(state.inactive || []);\nconst off = workflows.filter((w) => must.includes(String(w.id)) && !w.active);\nconst missing = must.filter((id) => !names[id]);\nconst newlyOff = off.filter((w) => !alerted.has(String(w.id)));\nconst backOn = [...alerted].filter((id) => !off.some((w) => String(w.id) === id) && names[id]);\nif (newlyOff.length || missing.some((id) => !alerted.has(id))) {\n  out.push({ send: true, kind: 'inactive', text: [`${cfg.client_name ? cfg.client_name + ': ' : ''}выключены воркфлоу, которые должны работать`,\n    ...newlyOff.map((w) => `• ${w.name}${ui ? '\\n  ' + ui + '/workflow/' + w.id : ''}`), ...missing.filter((id) => !alerted.has(id)).map((id) => `• воркфлоу ${id} не найден — удалён?`)].join('\\n') });\n}\nif (backOn.length) out.push({ send: true, kind: 'back', text: `Снова работают: ${backOn.map((id) => names[id]).join(', ')}` });\nstate.inactive = [...off.map((w) => String(w.id)), ...missing];\n\n// Morning digest, once a day.\nconst p = localParts(now);\nif (p.hour === (cfg.digest_hour === undefined ? 9 : cfg.digest_hour) && state.digest_date !== p.date) {\n  const day = executions.filter((e) => watched(e.workflowId) && at(e) > now - 24 * 60 * MIN);\n  const by = {};\n  for (const e of day) by[e.workflowId] = (by[e.workflowId] || 0) + 1;\n  const active = workflows.filter((w) => w.active && watched(w.id));\n  out.push({ send: true, kind: 'digest', text: [\n    `${cfg.client_name ? cfg.client_name + ' · ' : ''}n8n за сутки`,\n    `Активных воркфлоу: ${active.length}`,\n    day.length ? `Ошибок: ${day.length}` : 'Ошибок нет ✅',\n    ...Object.entries(by).sort((a, b) => b[1] - a[1]).slice(0, 10).map(([wf, n]) => `• ${names[wf] || wf}: ${n}`),\n    off.length ? `Выключены: ${off.map((w) => w.name).join(', ')}` : '',\n  ].filter(Boolean).join('\\n') });\n  state.digest_date = p.date;\n}\nstate.last_check = now;\nreturn out.length ? out.map((json) => ({ json: Object.assign({ chat: cfg.alert_chat_id }, json) })) : [{ json: { send: false } }];\n"
      },
