        "jsCode": "// Record Run — one side of an event arrives; when both are in, the results are compared.\nconst cfg = $('Config').first().json;\n// ---- shared helpers ----\nconst MIN = 60000;\nconst nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());\nconst digitsOf = (value) => String(value || '').replace(/[^\\d]/g, '');\n// Phones are stored in one international form, so the same person is recognised however they typed it.\nfunction phoneOf(value) {\n  const rules = cfg.phone || {};\n  let d = digitsOf(value);\n  if (d.startsWith('00')) d = d.slice(2);\n  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {\n    d = rules.country_code + d.slice(rules.national_prefix.length);\n  }\n  return d.length >= 9 && d.length <= 15 ? '+' + d : '';\n}\nfunction emailOf(value) {\n  const e = String(value || '').trim().toLowerCase();\n  return /^[^\\s@<>()\",;]+@[^\\s@<>()\",;]+\\.[a-z]{2,}$/.test(e) ? e : '';\n}\nconst localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {\n  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',\n}).format(new Date(ms));\nfunction localParts(ms) {\n  const parts = {};\n  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;\n  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };\n}\nconst sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;\nconst quoteSheet = (name) => \"'\" + String(name).replace(/'/g, \"''\") + \"'\";\n// ParallelRun sheet: one row per event, filled from both sides — the old platform and n8n.\nconst RCOLS = ['flow', 'key', 'first_at', 'status', 'old_at', 'old_result', 'new_at', 'new_result', 'diff'];\nconst colLetter = (index) => String.fromCharCode(65 + index);\nconst runsRange = () => `${quoteSheet(cfg.runs_sheet)}!A1:${colLetter(RCOLS.length - 1)}`;\nconst runRow = (row) => `${quoteSheet(cfg.runs_sheet)}!A${row}:${colLetter(RCOLS.length - 1)}${row}`;\nfunction runsTable(values) {\n  const all = values || [];\n  const header = all.length > 0 && String(all[0][0]).trim().toLowerCase() === 'flow';\n  return { header, rows: (header ? all.slice(1) : all).map((r, i) => ({ sheetRow: i + (header ? 2 : 1), run: Object.fromEntries(RCOLS.map((c, k) => [c, r[k] === undefined ? '' : String(r[k])])) })) };\n}\nconst putRun = (sheetRow, run) => ({ method: 'PUT', url: sheetUrl(encodeURIComponent(runRow(sheetRow))) + '?valueInputOption=RAW', body: { values: [RCOLS.map((c) => String(run[c] || ''))] } });\nconst appendRun = (run, hasHeader) => ({ method: 'POST', url: sheetUrl(encodeURIComponent(runsRange()) + ':append') + '?valueInputOption=RAW&insertDataOption=INSERT_ROWS',\n  body: { values: [...(hasHeader ? [] : [RCOLS]), RCOLS.map((c) => String(run[c] || ''))] } });\nconst pad = (n) => String(n).padStart(2, '0');\nconst stamp = (ms) => { const p = localParts(ms); return `${p.date} ${pad(p.hour)}:${pad(p.minute)}`; };\nconst parseStamp = (s) => { const m = /^(\\d{4})-(\\d{2})-(\\d{2}) (\\d{2}):(\\d{2})$/.exec(String(s)); if (!m) return Date.parse(s) || 0; const guess = Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4], +m[5]); const p = localParts(guess); return guess - (Date.UTC(+p.date.slice(0, 4), +p.date.slice(5, 7) - 1, +p.date.slice(8, 10), p.hour, p.minute) - guess); };\nconst plural = (n, one, few, many) => (n % 10 === 1 && n % 100 !== 11 ? one : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? few : many);\nconst req = $('Shadow Log').first().json;\nlet body = req.body || {};\nif (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }\nconst token = String(body.token || (req.headers || {})['x-shadow-token'] || (req.query || {}).token || '');\nif (!cfg.token || String(cfg.token).startsWith('REPLACE') || token !== String(cfg.token)) return [{ json: { ok: false, status: 403, response: { ok: false, error: 'bad token' } } }];\nconst flow = String(body.flow || '').trim().slice(0, 80);\nconst key = String(body.key || '').trim().slice(0, 120);\nconst system = String(body.system || '').toLowerCase();\nif (!flow || !key || !['old', 'new'].includes(system)) return [{ json: { ok: false, status: 422, response: { ok: false, error: 'flow, key and system (old|new) are required' } } }];\nlet result = body.result === undefined ? {} : body.result;\nif (typeof result === 'string') { try { result = JSON.parse(result); } catch (e) { result = { value: result }; } }\n\nconst rules = Object.assign({ fields: [], ignore: [] }, (cfg.compare || {})[flow] || {});\nconst ignore = new Set([...(cfg.ignore_fields || []), ...rules.ignore]);\n// Values are compared after light normalisation: trimmed text, numbers as numbers, case-insensitive emails.\nconst normal = (v) => {\n  if (v === null || v === undefined) return '';\n  if (typeof v === 'number' || typeof v === 'boolean') return String(v);\n  if (typeof v === 'object') return JSON.stringify(v, Object.keys(v).sort());\n  const s = String(v).trim().replace(/\\s+/g, ' ');\n  if (/^-?\\d+([.,]\\d+)?$/.test(s)) return String(Number(s.replace(',', '.')));\n  if (/^[^\\s@]+@[^\\s@]+$/.test(s)) return s.toLowerCase();\n  return s;\n};\nconst flat = (obj, prefix = '', out = {}) => {\n  if (obj && typeof obj === 'object' && !Array.isArray(obj)) { for (const [k, v] of Object.entries(obj)) flat(v, prefix ? `${prefix}.${k}` : k, out); }\n  else out[prefix || 'value'] = obj;\n  return out;\n};\nfunction compare(a, b) {\n  const fa = flat(a), fb = flat(b);\n  const keys = rules.fields.length ? rules.fields : [...new Set([...Object.keys(fa), ...Object.keys(fb)])].sort();\n  return keys.filter((k) => !ignore.has(k) && !ignore.has(k.split('.').pop())).filter((k) => normal(fa[k]) !== normal(fb[k]))\n    .map((k) => `${k}: ${String(normal(fa[k]) || '—').slice(0, 80)} → ${String(normal(fb[k]) || '—').slice(0, 80)}`);\n}\nconst table = runsTable($input.first().json.values);\nconst now = nowMs();\nconst found = table.rows.find(({ run }) => run.flow === flow && run.key === key);\nconst run = found ? Object.assign({}, found.run) : { flow, key, first_at: stamp(now), status: 'waiting' };\nrun[`${system}_at`] = stamp(now);\nrun[`${system}_result`] = JSON.stringify(result).slice(0, 4000);\nlet alert = '';\nif (run.old_result && run.new_result) {\n  const diff = compare(JSON.parse(run.old_result || '{}'), JSON.parse(run.new_result || '{}'));\n  const was = run.status;\n  run.status = diff.length ? 'mismatch' : 'match';\n  run.diff = diff.join('; ').slice(0, 1000);\n  if (diff.length && was !== 'mismatch') alert = [`Расхождение: ${flow}`, `Событие: ${key}`, ...diff.slice(0, 10).map((d) => `• ${d}`), diff.length > 10 ? `…и ещё ${diff.length - 10}` : ''].filter(Boolean).join('\\n');\n}\nreturn [{ json: { ok: true, status: 200, response: { ok: true, status: run.status }, http: found ? putRun(found.sheetRow, run) : appendRun(run, table.header), alert: Boolean(alert), chat: cfg.alert_chat_id, text: alert } }];\n"
